export const content: string = "# \ucf54\uc2a4\ud1a8\ub77c\ub2c8 1\uad8c \u2014 \ub3c8, \ub728\uac81\uac8c \uc0ac\ub791\ud558\uace0 \ucc28\uac11\uac8c \ub2e4\ub8e8\uc5b4\ub77c (\uc6d0\ubb38 \uc815\ub9ac\ubcf8)\n\n> **\ucd9c\ucc98:** YouTube \uc790\ub9c9 \uc790\ub3d9 \uc778\uc2dd\ubcf8\uc744 \uc0ac\ub78c\uc774 \uc77d\uae30 \uc88b\uac8c \uad50\uc815\u00b7\uc815\ub9ac\ud55c \ubb38\uc11c\uc785\ub2c8\ub2e4.  \n> **\uc800\uc790:** \uc559\ub4dc\ub808 \ucf54\uc2a4\ud1a8\ub77c\ub2c8 (Andr\u00e9 Kostolany, 1906\u20131999)  \n> **\ucc45 \uc9d1\ud544:** 1999\ub144 2\uc6d4, \ud5a5\ub144 93\uc138. \uac19\uc740 \ud574 9\uc6d4 \ud504\ub791\uc2a4\uc5d0\uc11c \ubcc4\uc138.\n\n---\n\n## \ubaa9\ucc28\n\n1. [\ub4e4\uc5b4\uac00\uba70 \u2014 \uc774 \ucc45\uacfc \uc774 \uc601\uc0c1\uc5d0 \ub300\ud558\uc5ec](#\ub4e4\uc5b4\uac00\uba70)\n2. [\ucf54\uc2a4\ud1a8\ub77c\ub2c8 80\ub144\uc744 \uc694\uc57d\ud558\ub294 \ub124 \ub2e8\uc5b4](#\ub124-\ub2e8\uc5b4-\uc694\uc57d)\n3. [\ud3ec\uc778\ud2b8 1 \u2014 \uc7ac\uc815\uc801 \ub3c5\ub9bd](#\ud3ec\uc778\ud2b8-1)\n4. [\ud3ec\uc778\ud2b8 2 \u2014 \ub3c8\uacfc \ub3c4\ub355](#\ud3ec\uc778\ud2b8-2)\n5. [\ud3ec\uc778\ud2b8 3 \u2014 \ub3c8\uacfc\uc758 \uac70\ub9ac](#\ud3ec\uc778\ud2b8-3)\n6. [\ud3ec\uc778\ud2b8 4 \u2014 \ub2e8\uc228\uc5d0 \ubc31\ub9cc\uc7a5\uc790 \ub418\ub294 3\uac00\uc9c0 \ubc29\ubc95](#\ud3ec\uc778\ud2b8-4)\n7. [\ud3ec\uc778\ud2b8 5 \u2014 \ud22c\uc790\ub294 \uc608\uc220\uc774\ub2e4](#\ud3ec\uc778\ud2b8-5)\n8. [\ud3ec\uc778\ud2b8 6 \u2014 \ud22c\uc790\ub97c \ud560 \uac83\uc774\ub0d0 \ub9d0 \uac83\uc774\ub0d0](#\ud3ec\uc778\ud2b8-6)\n9. [\ud3ec\uc778\ud2b8 7 \u2014 \uc911\uac1c\uc778(\ube0c\ub85c\ucee4)](#\ud3ec\uc778\ud2b8-7)\n10. [\ud3ec\uc778\ud2b8 8 \u2014 \uba38\ub2c8 \ub9e4\ub2c8\uc800\u00b7\uc790\uc0b0\uad00\ub9ac\uc0ac](#\ud3ec\uc778\ud2b8-8)\n11. [\ud3ec\uc778\ud2b8 9 \u2014 \uae08\uc735\uc790\ubcf8\uac00\uc640 \ud070 \uc190](#\ud3ec\uc778\ud2b8-9)\n12. [\ud3ec\uc778\ud2b8 10 \u2014 \ub2e8\uae30 \ud22c\uc790\uc790](#\ud3ec\uc778\ud2b8-10)\n13. [\ud3ec\uc778\ud2b8 11 \u2014 \uc7a5\uae30 \ud22c\uc790\uc790](#\ud3ec\uc778\ud2b8-11)\n14. [\ud3ec\uc778\ud2b8 12 \u2014 \uc21c\uc885 \ud22c\uc790\uc790 (\uc6b0\ub9ac\uc758 \ubaa9\ud45c)](#\ud3ec\uc778\ud2b8-12)\n15. [\ud3ec\uc778\ud2b8 13 \u2014 \uc8fc\uc2dd: \uac00\uc7a5 \ud070 \ud22c\uc790 \ub300\uc0c1](#\ud3ec\uc778\ud2b8-13)\n16. [\ud3ec\uc778\ud2b8 14 \u2014 \uc8fc\uc2dd\uc2dc\uc7a5\uc740 \uc790\ubcf8\uc8fc\uc758\uc758 \uc911\ucd94\uc2e0\uacbd](#\ud3ec\uc778\ud2b8-14)\n17. [\ud3ec\uc778\ud2b8 15 \u2014 \ud22c\uc790\uc790\uac00 \uc544\ub294 \uac83\uacfc \ubaa8\ub974\ub294 \uac83](#\ud3ec\uc778\ud2b8-15)\n18. [\ud3ec\uc778\ud2b8 16 \u2014 \uacbd\uc81c\uc640 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uad00\uacc4: \uac1c\uc640 \uc8fc\uc778](#\ud3ec\uc778\ud2b8-16)\n19. [\ud3ec\uc778\ud2b8 17 \u2014 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uace0\uc720 \ub17c\ub9ac](#\ud3ec\uc778\ud2b8-17)\n20. [\ud3ec\uc778\ud2b8 18 \u2014 \uc8fc\uc2dd\uc2dc\uc7a5\uc744 \uc9c0\ubc30\ud558\ub294 \uc720\uc77c\ud55c \ub17c\ub9ac: \uacf5\uae09\uacfc \uc218\uc694](#\ud3ec\uc778\ud2b8-18)\n21. [\ud3ec\uc778\ud2b8 19 \u2014 \uacf5\uae09\uacfc \uc218\uc694\uc758 \ud575\uc2ec \uc6d0\ub9ac](#\ud3ec\uc778\ud2b8-19)\n22. [\ud3ec\uc778\ud2b8 20 \u2014 \uc7a5\uae30\uc801 \uba5c\ub85c\ub514: \uc804\uc7c1\uacfc \ud3c9\ud654](#\ud3ec\uc778\ud2b8-20)\n23. [\ud3ec\uc778\ud2b8 21 \u2014 \uc911\uae30\uc801 \uba5c\ub85c\ub514: \ub3c8\uacfc \uc2ec\ub9ac](#\ud3ec\uc778\ud2b8-21)\n24. [\ud3ec\uc778\ud2b8 21(\ubcf4\ucda9) \u2014 \uacbd\uae30\ub294 \uc911\uae30\uc801\uc73c\ub85c \uc8fc\uac00\uc640 \ubb34\uad00\ud558\ub2e4](#\ud3ec\uc778\ud2b8-21-\ubcf4\ucda9)\n25. [\ud3ec\uc778\ud2b8 22 \u2014 \uc778\ud50c\ub808\uc774\uc158\uacfc \uae08\ub9ac](#\ud3ec\uc778\ud2b8-22)\n26. [\ud3ec\uc778\ud2b8 23 \u2014 \uae08\ub9ac: \uc8fc\uac00\uc5d0 \uac00\uc7a5 \ud070 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc694\uc18c \u2605\ud575\uc2ec\u2605](#\ud3ec\uc778\ud2b8-23)\n27. [\ud3ec\uc778\ud2b8 24 \u2014 \uc18c\uc2e0\ud30c vs. \ubd80\ud654\ub1cc\ub3d9\ud30c / \uc131\uacf5 \ud22c\uc790\uc790\uc758 4G](#\ud3ec\uc778\ud2b8-24)\n28. [\ud3ec\uc778\ud2b8 25 \u2014 \uc0dd\uac01](#\ud3ec\uc778\ud2b8-25)\n29. [\ud3ec\uc778\ud2b8 26 \u2014 \uc778\ub0b4](#\ud3ec\uc778\ud2b8-26)\n30. [\ud3ec\uc778\ud2b8 27 \u2014 \ud589\uc6b4](#\ud3ec\uc778\ud2b8-27)\n31. [\ud3ec\uc778\ud2b8 28 \u2014 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 \ub2ec\uac40](#\ud3ec\uc778\ud2b8-28)\n32. [\ud3ec\uc778\ud2b8 29 \u2014 \ubd90\uacfc \ud3ed\ub77d\uc740 \ubd84\ub9ac\ud560 \uc218 \uc5c6\ub294 \uc30d\ub465\uc774](#\ud3ec\uc778\ud2b8-29)\n33. [\ud3ec\uc778\ud2b8 30 \u2014 \ud3ed\ub77d\uc758 \uc120\ud589 \uc870\uac74](#\ud3ec\uc778\ud2b8-30)\n34. [\ud3ec\uc778\ud2b8 31 \u2014 \ud504\ub791\uc2a4 \uc8fc\uc2dd\uc2dc\uc7a5\uc744 \ud30c\uba78\ub85c \uc774\ub048 \uc5ed\uc0ac\uc801 \uc0ac\ub840](#\ud3ec\uc778\ud2b8-31)\n35. [\ud3ec\uc778\ud2b8 32 \u2014 \uc131\uacf5 \uc804\ub7b5: \ub0a8\ub4e4\uacfc \ubc18\ub300\ub85c](#\ud3ec\uc778\ud2b8-32)\n36. [\ud3ec\uc778\ud2b8 33 \u2014 \uac70\ub798\ub7c9\uc774 \uc554\uc2dc\ud558\ub294 \uac83](#\ud3ec\uc778\ud2b8-33)\n37. [\ud3ec\uc778\ud2b8 34 \u2014 \uac00\uc7a5 \ubd84\uba85\ud55c \uc554\uc2dc: \uc5ec\ub860](#\ud3ec\uc778\ud2b8-34)\n38. [\ud3ec\uc778\ud2b8 35 \u2014 \ub69c\ub837\ud55c \uc8fc\uad00: \uc131\uacf5\uc758 \uc870\uac74](#\ud3ec\uc778\ud2b8-35)\n39. [\ud3ec\uc778\ud2b8 36 \u2014 \ud604\uae08 \ud750\ub984\uc774 \ub9c9\ud788\uba74 \uacfc\uac10\ud788 \ube60\uc838\ub098\uc640\ub77c](#\ud3ec\uc778\ud2b8-36)\n40. [\ud3ec\uc778\ud2b8 37 \u2014 \uacf5\ub9e4\ub3c4 \uacbd\ud5d8\ub2f4](#\ud3ec\uc778\ud2b8-37)\n41. [\ud3ec\uc778\ud2b8 38 \u2014 \uc815\ubcf4: \uc18c\uc790\uc758 \ub3c4\uad6c](#\ud3ec\uc778\ud2b8-38)\n42. [\ud3ec\uc778\ud2b8 39 \u2014 \uacf5\uc2dc\u00b7\uc2e4\uc801 \ubc1c\ud45c\ub97c \ubcf4\uace0 \ud22c\uc790\ud558\uc9c0 \ub9c8\ub77c](#\ud3ec\uc778\ud2b8-39)\n43. [\ud3ec\uc778\ud2b8 40 \u2014 \ucc38\ub41c \uc8fc\uc2dd \uc9c0\uc2dd\uc774\ub780](#\ud3ec\uc778\ud2b8-40)\n44. [\ud3ec\uc778\ud2b8 41 \u2014 \uc99d\uad8c\uc0ac \ucd94\ucc9c \uc885\ubaa9\uc758 \uc2e4\uccb4](#\ud3ec\uc778\ud2b8-41)\n45. [\ud3ec\uc778\ud2b8 42 \u2014 \uc77c\ubc18\uc801 \ucd94\uc138\ub97c \uba3c\uc800 \ud30c\uc545\ud558\ub77c](#\ud3ec\uc778\ud2b8-42)\n46. [\ud3ec\uc778\ud2b8 43 \u2014 \uc5b4\ub5a4 \uc0b0\uc5c5\uc774 \uc55e\uc73c\ub85c \uc720\ub9dd\ud55c\uac00](#\ud3ec\uc778\ud2b8-43)\n47. [\ud3ec\uc778\ud2b8 44 \u2014 \uc131\uc7a5 \uc0b0\uc5c5\uc758 \ub77c\uc774\ud504\uc0ac\uc774\ud074](#\ud3ec\uc778\ud2b8-44)\n48. [\ud3ec\uc778\ud2b8 45 \u2014 \ud30c\uc0b0 \uc704\uae30 \uae30\uc5c5\uc5d0 \uc8fc\ubaa9\ud558\ub77c: \ud06c\ub77c\uc774\uc2ac\ub7ec \uc0ac\ub840](#\ud3ec\uc778\ud2b8-45)\n49. [\ud3ec\uc778\ud2b8 46 \u2014 '\ubcf4\uc720\ud558\ub77c'\ub294 \ub9d0\uc758 \ud568\uc815](#\ud3ec\uc778\ud2b8-46)\n50. [\ud3ec\uc778\ud2b8 47 \u2014 \ucc28\ud2b8 \ubd84\uc11d\uc758 \ud55c\uacc4](#\ud3ec\uc778\ud2b8-47)\n51. [\ud3ec\uc778\ud2b8 48 \u2014 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uac00 \uc778\uc815\ud558\ub294 \ub450 \uac00\uc9c0 \ucc28\ud2b8 \uc774\ub860](#\ud3ec\uc778\ud2b8-48)\n52. [\ud3ec\uc778\ud2b8 49 \u2014 \uba38\ub2c8 \ub9e4\ub2c8\uc800\u00b7\ud5e4\uc9c0\ud380\ub4dc\uc5d0 \ub300\ud558\uc5ec](#\ud3ec\uc778\ud2b8-49)\n53. [\ud3ec\uc778\ud2b8 50 \u2014 \uc190\uc2e4\ub3c4 \ud22c\uc790\uc758 \uc77c\ubd80](#\ud3ec\uc778\ud2b8-50)\n54. [\ud3ec\uc778\ud2b8 51 \u2014 10\uac00\uc9c0 \ud589\ub3d9 \uc6d0\uce59](#\ud3ec\uc778\ud2b8-51)\n55. [\ud3ec\uc778\ud2b8 52 \u2014 10\uac00\uc9c0 \uae08\uae30\uc0ac\ud56d](#\ud3ec\uc778\ud2b8-52)\n56. [\ub9c8\uce58\uba70](#\ub9c8\uce58\uba70)\n\n---\n\n## \ub4e4\uc5b4\uac00\uba70\n\n\uc8fc\uc2dd \uad00\ub828 \uc720\uba85 \ucc44\ub110\uc758 \uc601\uc0c1 50\ud3b8\uc744 \ubcf4\ub294 \uac83\ubcf4\ub2e4, \uc774 \uc601\uc0c1\uc744 \uc5ec\ub7ec \ubc88 \ub3cc\ub824 \ubcf4\ub294 \uac83\uc774 \ubc31 \ubc30 \uc720\uc775\ud558\ub2e4\uace0 \ud655\uc5b8\ud55c\ub2e4. \ud55c\ud3c9\uc0dd \ud22c\uc790\uc5d0 \ubab8\ub2f4\uc740 \uc559\ub4dc\ub808 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 \uc774\ub984\uc740 \uc790\ub3d9 \uc778\uc2dd \uacfc\uc815\uc5d0\uc11c \uc885\uc885 \uc624\ud0c1\uc790\ub85c \ud45c\uae30\ub418\uc9c0\ub9cc, \uc62c\ubc14\ub978 \ud45c\uae30\ub294 **\ucf54\uc2a4\ud1a8\ub77c\ub2c8(Andr\u00e9 Kostolany)**\uc774\ub2e4.\n\n\uc6b0\ub9ac\uac00 \uc8fc\ubaa9\ud574\uc57c \ud560 \ucc45\uc740 \uadf8\uac00 \uc8fd\uae30 \uc804\uc5d0 \uc4f4 \ub9c8\uc9c0\ub9c9 \uc5ed\uc791, **\u300e\ub3c8, \ub728\uac81\uac8c \uc0ac\ub791\ud558\uace0 \ucc28\uac11\uac8c \ub2e4\ub8e8\uc5b4\ub77c\u300f**\uc774\ub2e4. \uc720\ub7fd \uc99d\uad8c\uacc4\ub294 \uc774 \ucc45\uc744 \"\uc704\ub300\ud55c \uc720\uc0b0\"\uc774\ub77c\uace0 \ud3c9\uac00\ud55c\ub2e4. **80\ub144 \ud22c\uc790 \uacbd\ud5d8\uc774 \ub179\uc544\uc788\ub294 \ud22c\uc790\uc11c\uc758 \ubc31\ubbf8**\uc774\uba70, \uc194\uc9c1\ud788 \ucc45\uc744 \uae30\uc900\uc73c\ub85c \ubcf4\uc790\uba74 \uc6cc\ub7f0 \ubc84\ud54f\ubcf4\ub2e4 \ub354 \ub098\uc740 \ub4ef\ud558\ub2e4.\n\n\uc774 \ucc45\uc758 \uc81c\ubaa9\uc740 \uc798\ubabb\ub418\uc5b4\ub3c4 \ud06c\uac8c \uc798\ubabb\ub418\uc5c8\ub2e4. \uc65c\ub0d0\ud558\uba74 \uc774 \ucc45\uc740 \ub3c8\ubcf4\ub2e4\ub294 \uc8fc\uc2dd\ud22c\uc790\uc5d0 \ub354 \ucd08\uc810\uc774 \ub9de\ucdb0\uc838 \uc788\uc73c\uba70, **\uc8fc\uc2dd\ud22c\uc790\ub85c \ub3c8\uc744 \ubc8c \uc218\ubc16\uc5d0 \uc5c6\ub294 \ubc29\ubc95\uc774 \uc790\uc138\ud788 \uae30\uc220\ub418\uc5b4 \uc788\uae30 \ub54c\ubb38**\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc81c\ubaa9\uc774 \ubc14\ub00c\uc9c0 \uc54a\uc558\uc73c\uba74 \ud55c\ub2e4. \ub2e8\uc21c\ud788 \ub3c8\uc5d0 \ub300\ud55c \uc785\ubb38\uc11c \uc815\ub3c4\ub85c \ucc29\uac01\ud558\uc5ec \uc8fc\uc2dd \ud22c\uc790\uc790\ub4e4\uc774 \uc27d\uac8c \uc9c0\ub098\uce58\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\uc5d0\uc11c\ub2e4.\n\n\uc774 \uc601\uc0c1\uc744 \ub05d\uae4c\uc9c0 \uc2dc\uccad\ud55c\ub2e4\uba74 \uc5ec\ub7ec\ubd84\uc740 80\ub144\uc758 \uc2dc\uac04\uc744 \ubc88 \uc148\uc774\ub2e4. \uc624\ub298 \uc601\uc0c1\uc5d0\uc11c\ub294 \uadf8 \uc911\uc5d0\uc11c\ub3c4 \ud575\uc2ec\uc774\ub77c \ud560 \uc218 \uc788\ub294 **\ucd1d 52\uac1c\uc758 \ud575\uc2ec \ud3ec\uc778\ud2b8**\ub97c \uc124\uba85\ud55c\ub2e4. \uadf8 \uc911\uc5d0\uc11c\ub3c4 **\ud3ec\uc778\ud2b8 23\ubc88\uc758 \ub0b4\uc6a9\uc774 \uc774 \uc601\uc0c1\uc758 \ud575\uc2ec \uc911\uc758 \ud575\uc2ec**\uc774\ub2e4.\n\n---\n\n## \ub124 \ub2e8\uc5b4 \uc694\uc57d\n\n**\ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 80\ub144 \uc8fc\uc2dd \uc778\uc0dd\uc744 \ub531 \ub124 \ub2e8\uc5b4\ub85c \uc694\uc57d\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\ub2e4:**\n\n> **\uc0dd\uac01 \u00b7 \uacf5\uae09\uacfc \uc218\uc694 \u00b7 \uae08\ub9ac \u00b7 \ub2ec\uac40**\n\n\uc774 \ub124 \uac00\uc9c0 \ub2e8\uc5b4\ub97c \ud56d\uc0c1 \uba38\ub9bf\uc18d\uc5d0 \ub450\uace0 \uc544\ub798 \ub0b4\uc6a9\uc744 \uc77d\uc5b4 \ub098\uac00\uae38 \ubc14\ub780\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 1\n\n**\uc7ac\uc815\uc801 \ub3c5\ub9bd\uc740 \uac74\uac15 \ub2e4\uc74c\uc73c\ub85c \uc911\uc694\ud55c \ucd5c\uace0\uc758 \uc120\uc774\uba70 \uac00\uc7a5 \uadc0\ud55c \uac83\uc774\ub2e4.** \ub3c5\ub9bd\uc758 \uc758\ubbf8\ub294 \ud558\uace0 \uc2f6\uc740 \uac83\uc744 \ud558\uace0, \ud558\uae30 \uc2eb\uc740 \uac83\uc744 \ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub294 \uc0c1\ud0dc\ub97c \ub9d0\ud55c\ub2e4. \ub3c8\uc774 \uc544\ubb34\ub9ac \ub9ce\uc544\ub3c4 \ub3c5\ub9bd\uc744 \uc774\ub8e8\uc9c0 \ubabb\ud588\ub2e4\uba74 \uc9c4\uc815\ud55c \ubd80\uc790\uac00 \uc544\ub2c8\ub2e4. \uc989, \ud558\uae30 \uc2eb\uc740 \uac83\uc744 \ud558\uba74\uc11c \ubd80\uc790\uac00 \ub41c \uc0ac\ub78c\uc740 \uc9c4\uc815\ud55c \ubd80\uc790\uac00 \uc544\ub2c8\ub2e4. \uc800\uc790\ub294 \ud22c\uc790, \uadf8 \uc911\uc5d0\uc11c\ub3c4 \uc8fc\uc2dd\ud22c\uc790\ub97c \ud1b5\ud574 \uc7ac\uc815\uc801 \ub3c5\ub9bd\uc744 \uc774\ub8e8\uc5c8\uace0 \uadf8\uac83\uc744 \ucda9\ubd84\ud788 \ub204\ub838\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 2\n\n\ub3c8\uc740 \ub9e4\ub825\uc801\uc774\uba70 \uacbd\uc81c\uc801 \uc9c4\ubcf4\uc758 \ub3d9\ub825\uc774\uc790 \ud589\ubcf5\uc758 \uc218\ub2e8\uc774\ub2e4. **\ub3c8\uc774 \ube44\ub3c4\ub355\uc801\uc774\ub77c\uace0 \ud55c\ub2e4\uba74, \uadf8 \uc774\uba74\uc5d0\ub294 \uc815\uc758\ub85c\uc6c0\uc744 \uac00\uc7a5\ud55c \uc9c8\ud22c\uac00 \ubd88\ud0c0\uace0 \uc788\ub2e4.** \uc5b4\ub290 \ub204\uad6c\ub3c4 \ub3c8\uc5d0 \ub300\ud574 \ub9d0\ud558\uc9c0 \uc54a\uc9c0\ub9cc, \ubaa8\ub4e0 \uc0ac\ub78c\ub4e4\uc740 \ub3c8\uc744 \uc0dd\uac01\ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 3\n\n\ub3c8\uc740 \uba40\uc9c0\ub3c4 \uac00\uae5d\uc9c0\ub3c4 \uc54a\uac8c \uac70\ub9ac\ub97c \uc720\uc9c0\ud574\uc57c \ud55c\ub2e4. **\ub3c8\uc744 \uadf8\ub0e5 \ub530\ub77c\uac00\uc11c\ub294 \uc548 \ub418\uba70, \uc815\uba74\uc73c\ub85c \ubd80\ub52a\ud600\uc57c \ud558\ub294 \ub300\uc0c1\uc774\ub2e4.** \uc8fc\uac00\ub97c \ub4a4\ucad3\uc544\uac00\uae30\ubcf4\ub2e4\ub294 \ub5a8\uc5b4\uc9c0\uace0 \uc788\ub294 \uc8fc\uac00\uc758 \uc815\uba74\uc73c\ub85c \ubd80\ub52a\ud600\uc57c \ud55c\ub2e4. \ub3c8\uc5d0 \ub300\ud55c \uc5f4\uc815\uc774 \uc778\uc0c9\ud568\uc774\ub098 \ubcd1\uc801\uc778 \ud22c\uc790\ub85c \ubcc0\uc9c8\ub418\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc783\uc5b4\ubc84\ub9b4 \uc218\ub3c4 \uc788\ub2e4\ub294 \uac83\uc744 \ud56d\uc0c1 \uc0c1\uc0c1\ud558\uba70 \ud22c\uc790\ud574\uc57c \uac74\uac15\ud55c \ud22c\uc790\ub97c \ud560 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c **\ub3c8\uc744 \uc0ac\ub791\ud558\uba74\uc11c\ub3c4 \ucc28\uac11\uac8c \ubc84\ub9b4 \uc218 \uc788\ub294 \uc0ac\ub78c\uc774 \ubd80\ub97c \ub204\ub9b4 \uc218 \uc788\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 4\n\n\ub2e8\uc228\uc5d0 \ubc31\ub9cc\uc7a5\uc790\uac00 \ub418\ub294 3\uac00\uc9c0 \ubc29\ubc95:\n\n1. \ubd80\uc720\ud55c \ubc30\uc6b0\uc790\ub97c \ub9cc\ub09c\ub2e4\n2. \uc720\ub9dd\ud55c \uc0ac\uc5c5 \uc544\uc774\ud15c\uc744 \ucc3d\uc5c5\ud55c\ub2e4\n3. **\ud22c\uc790\ub97c \ud55c\ub2e4**\n\n\uc800\uc790\uc758 \uc804\ubb38 \uc601\uc5ed\uc740 \ud22c\uc790\uc774\uba70, \ud22c\uc790\ub85c \ub2e8\uc228\uc5d0 \ubc31\ub9cc\uc7a5\uc790\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 5\n\n**\ud22c\uc790\ub294 \uacfc\ud559\uc774 \uc544\ub2cc \uc608\uc220\uc774\ub2e4.** \ud22c\uc790\ub294 \ub54c\ub85c\ub294 \ub2e4\ub9ac\ub97c \uc704\ub85c \uce58\ucf1c\ub4e4\uace0 \uba38\ub9ac\ub294 \uc544\ub798\ub85c \ud5a5\ud558\uac8c \ud574\uc57c \ud55c\ub2e4. \uc989, \ud22c\uc790\ub294 \ub9d0\ub85c \uc124\uba85\ud560 \uc218 \uc5c6\ub294 \ucd08\ud604\uc2e4\uc8fc\uc758\uc5d0 \ub300\ud55c \uc774\ud574\uac00 \uc808\ub300\uc801\uc73c\ub85c \ud544\uc694\ud558\ub2e4. \ud22c\uc790\uc790\uac00 \ub41c\ub2e4\ub294 \uac83\uc740 \uc544\uc8fc \uba4b\uc9c4 \uc77c\uc774\uba70, \uc740\ud1f4 \uad6d\uba74\uc5d0 \ub4e4\uc5b4\uac00\uba74 \ub354\uc6b1 \uadf8\ub807\ub2e4. **\ud22c\uc790\ub294 \ub098\uc774\uac00 \ub4e4\uc218\ub85d \uc810\uc810 \ud544\uc694\ud558\uac8c \ub418\ub294 \uc815\uc2e0\uc801 \uccb4\uc870\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 6\n\n> \ub3c8\uc774 \ub9ce\uc740 \uc0ac\ub78c\uc740 \ud22c\uc790\ub97c \ud560 \uc218 \uc788\ub2e4.  \n> \ub3c8\uc774 \uc870\uae08\ubc16\uc5d0 \uc5c6\ub294 \uc0ac\ub78c\uc740 \ud22c\uc790\ub97c \ud574\uc120 \uc548 \ub41c\ub2e4.  \n> \uadf8\ub7ec\ub098 \ub3c8\uc774 \uc804\ud600 \uc5c6\ub294 \uc0ac\ub78c\uc740 \ubc18\ub4dc\uc2dc \ud22c\uc790\ud574\uc57c \ud55c\ub2e4.\n\n\uccab \ubc88\uc9f8\ub294 \uc790\uc2e0\uc758 \uac00\uc871\uc744 \ubd80\uc591\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\uc774\ub77c\ub294 \uc758\ubbf8\uc774\uace0, \uc138 \ubc88\uc9f8\ub294 \uc800\uc790 \uc2a4\uc2a4\ub85c \ubaa8\uc21c\uc774\ub77c\uace0 \uc778\uc815\ud588\ub2e4. \uc65c\ub0d0\ud558\uba74 \ud22c\uc790\ub97c \ud558\uae30 \uc704\ud574\uc11c\ub294 \ub3c8\uc774 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. **\uc815\ub9d0 \uc88b\uc740 \uc544\uc774\ub514\uc5b4\uac00 \uc788\ub2e4\uba74 \uc544\uc8fc \uc801\uc740 \uae08\uc561\uc73c\ub85c\ub3c4 \ub192\uc740 \uc218\uc775\uc744 \uac70\ub458 \uc218 \uc788\ub2e4**\uace0 \uc800\uc790\ub294 \uac15\uc870\ud55c\ub2e4. \uc8fc\uc2dd\ud22c\uc790\uc5d0 \ub6f0\uc5b4\ub4e4\ub824\uba74 \uae30\uaebc\uc774 \uc704\ud5d8\uc744 \uac10\uc218\ud574\uc57c \ud55c\ub2e4\ub294 \uc815\uc2e0\uc801 \uc900\ube44 \uc6b4\ub3d9\uc774 \ud544\uc694\ud558\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 7\n\n\uc911\uac1c\uc778(\ube0c\ub85c\ucee4)\uc740 \uc8fc\uc2dd \uc911\uac1c \uc2dc\uc7a5\uc758 \ud615\uc131\uc790\uc774\ub2e4. \uadf8\ub4e4\uc740 \uace0\uac1d\uc758 \uc218\uc218\ub8cc\ub85c \ub3c8\uc744 \ubc88\ub2e4. **\uc8fc\uc2dd\ud22c\uc790\ub85c \ub3c8\uc744 \ubc84\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc544\ub2c8\ub2e4.** \uc800\uc790 \uc5ed\uc2dc \ud55c\ub54c \ube0c\ub85c\ucee4\uc600\uae30 \ub54c\ubb38\uc5d0 \uadf8\ub4e4\uc744 \ub0ae\uac8c \ud3c9\uac00\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uba38\ub9ac\uac00 \uadf8\ub807\uac8c \uc88b\uc740 \ud3b8\uc774 \uc544\ub2c8\uc9c0\ub9cc \uaf2d \ud544\uc694\ud55c \uc874\uc7ac\ub4e4\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 8\n\n\uba38\ub2c8 \ub9e4\ub2c8\uc800, \ud5e4\uc9c0\ud380\ub4dc \ub9e4\ub2c8\uc800, \uc790\uc0b0\uad00\ub9ac\uc0ac \ub4f1\uc774 \ud3ec\ud568\ub41c\ub2e4. \uadf8\ub4e4\ub3c4 \ube0c\ub85c\ucee4\uc640 \ube44\uc2b7\ud558\ub2e4. **\uadf8\ub4e4\uc758 \ud22c\uc790 \uc131\uacf5\ub960\uc740 \uadf8\ub2e4\uc9c0 \ub192\uc9c0 \uc54a\ub2e4.** \uc65c\ub0d0\ud558\uba74 \uadf8\ub4e4 \uc911 \uc2dc\uc7a5\uc744 \uc815\ud655\ud788 \uc608\uce21\ud560 \uc218 \uc788\ub294 \ub2a5\ub825\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \uc5bc\ub9c8 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. 80\ub144 \uacbd\ud5d8\uc73c\ub85c \ud558\ub294 \ub9d0\uc774\ub2c8 \ubbff\uc5b4\ub77c.\n\n---\n\n## \ud3ec\uc778\ud2b8 9\n\n\uae08\uc735\uc790\ubcf8\uac00\uc640 \uc2dc\uc7a5\uc758 \ud070 \uc190 \u2014 \uc790\uae30 \uc7ac\uc0b0\uc744 \uac00\uc9c0\uace0 \uc8fc\uc2dd\uc744 \ud558\ub294 \uc0ac\ub78c \ubaa8\ub450\ub97c \ud22c\uc790\uc790\ub85c \ubcfc \uc218 \uc5c6\ub2e4. **\uadf8\ub4e4\uc758 \uad00\uc2ec\uc740 \uc8fc\uc2dd\uc774 \uc544\ub2c8\ub77c \ub2e8\uae30 \uac70\ub798 \uadf8 \uc790\uccb4\uc5d0 \ucd08\uc810\uc744 \ub450\uace0 \uc788\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 10\n\n\ub2e8\uae30 \ud22c\uc790\uc790 \u2014 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uc0ac\uae30\uafbc. \uadf8\ub4e4\uc740 \ud22c\uc790\uc790\ub77c\ub294 \uce6d\ud638\ub97c \ub4e4\uc744 \uc790\uaca9\uc774 \uc5c6\ub2e4. \ub2e8\uae30\uac04\uc5d0 \ud070\ub3c8\uc744 \ubc8c \uc218 \uc788\uc9c0\ub9cc \uc7a5\uae30\uc801\uc73c\ub85c\ub294 \ub9dd\ud560 \uac83\uc774 \ud2c0\ub9bc\uc5c6\ub2e4. **80\ub144\uac04 \uc99d\uad8c\uacc4\uc5d0 \ubab8\ub2f4\uc544 \uc654\uc9c0\ub9cc \uc7a5\uae30\uc801\uc73c\ub85c \uc131\uacf5\ud55c \ub2e8\uae30 \ud22c\uc790\uc790\ub97c \ubcf8 \uc801 \uc5c6\ub2e4.** \uc740\ud589\uacfc \ube0c\ub85c\ucee4\ub4e4\uc740 \uace0\uac1d\uc744 \ub2e8\uae30 \ud22c\uc790\uc790\ub85c \ub9cc\ub4e4\uae30 \uc704\ud574 \ubcc4\uc758\ubcc4 \uc218\ub2e8\uc744 \ub2e4 \uc4f4\ub2e4. \ub2e8\uae30 \ud22c\uc790\uac00 \ud65c\uc131\ud654\ub420\uc218\ub85d \uadf8\ub4e4\uc774 \ucde8\ud558\ub294 \uc218\uc218\ub8cc\uac00 \ub9ce\uc544\uc9c0\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 11\n\n\uc7a5\uae30 \ud22c\uc790\uc790 \u2014 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \ub9c8\ub77c\ud1a0\ub108. \uadf8\ub4e4\uc740 \uc218\uc2ed \ub144 \ub4a4\uc758 \ub178\ud6c4 \ub300\ucc45\uc774\ub098 \uc720\uc0b0\uc73c\ub85c \uc8fc\uc2dd\uc744 \uc0b0\ub2e4. \uc6b0\ub7c9\uc8fc\uc5d0 \ud22c\uc790\ud558\uba70 \ubaa8\ub4e0 \uc885\ubaa9\uacfc \uc5ec\ub7ec \ub098\ub77c\uc5d0 \uace8\uace0\ub8e8 \ubd84\uc0b0 \ud22c\uc790\ud55c\ub2e4. \uc804\ub9dd\uc774 \uc88b\uc740 \uc885\ubaa9\uc744 \uc7ac\ube68\ub9ac \uc0ac\ub4e4\uc774\ub294 \ub4f1\uc758 \ub2e8\uae30 \uc2dc\ub3c4\ub97c \ud558\uc9c0 \uc54a\ub294\ub2e4. **\uc7a5\uae30 \ud22c\uc790\ub294 \ubaa8\ub4e0 \uc8fc\uc2dd \uac70\ub798 \uc911 \ucd5c\uace0\uc758 \uacb0\uacfc\ub97c \ub0b3\ub294 \ubc29\ubc95\uc774\uba70, \uc801\uc740 \uae08\uc561\uc758 \ub3c8\uc73c\ub85c \ubc31\ub9cc\uc7a5\uc790\uac00 \ub420 \uc218 \uc788\ub294 \uac00\uc7a5 \ud6a8\uc728\uc801\uc778 \ubc29\ubc95\uc774\ub2e4.**\n\n> \uc815\uc9c1\ud558\uac8c \ub9d0\ud558\ub77c\uace0 \ud55c\ub2e4\uba74, \ub098\ub294 \uc5ec\ub7ec\ubd84\ub4e4\uc5d0\uac8c \uc7a5\uae30 \ud22c\uc790\ub97c \uad8c\ud558\uace0 \uc2f6\ub2e4. \ub9cc\uc57d \uc5ec\ub7ec\ubd84\ub4e4\uc774 \ub098\uc758 \ub9d0\uc744 \ubbff\uace0 \uc7a5\uae30 \ud22c\uc790\ub97c \ud55c\ub2e4\uba74, \ub098\ub294 \uc774 \ucc45\uc744 \uc5ec\uae30\uc11c \ub05d\ub9c8\uccd0\uc57c \ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 12\n\n\uc21c\uc885 \ud22c\uc790\uc790 \u2014 \uc7a5\uae30\uc801 \uc804\ub7b5\uac00, \uc6b0\ub9ac\uc758 \ubaa9\ud45c. \uc21c\uc885 \ud22c\uc790\ub294 \ub2e8\uae30 \ud22c\uc790\uc790\uc640 \uc7a5\uae30 \ud22c\uc790\uc790\uc758 \uc911\uac04\ucbe4\uc774\ub2e4. \ubaa8\ub4e0 \ub274\uc2a4\uc5d0 \ud765\ubbf8\ub97c \uac00\uc9c0\ub418 \ubaa8\ub4e0 \ub274\uc2a4\uc5d0 \ubc18\uc751\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud22c\uc790\ub97c \uae08\ubc29 \ud3ec\uae30\ud558\uc9c0 \uc54a\uc73c\uba70, \ub274\uc2a4\uac00 \ub108\ubb34 \uacb0\uc815\uc801\uc774\uc5b4\uc11c \uc790\uc2e0\uc758 \ud310\ub2e8 \uae30\ucd08\uac00 \ud754\ub4e4\ub9b4 \ub54c, \uae30\uc874\uc758 \ud310\ub2e8\uc5d0 \uc704\ubc30\ub420 \ub54c \ube44\ub85c\uc18c \uc6c0\uc9c1\uc778\ub2e4.\n\n**\uadf8\ub4e4\uc740 \uc790\uc2e0\ub9cc\uc758 \uc544\uc774\ub514\uc5b4\uc640 \uc2a4\ud0c0\uc77c\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4. \uc774\uac83\uc774 \ub2e8\uae30 \ud22c\uc790\uc790\uc640 \uadf8\ub4e4\uc744 \uad6c\ubd84\ud558\ub294 \uacb0\uc815\uc801 \ucc28\uc774\ub2e4.** \uadf8\ub4e4\ub9cc\uc758 \ube44\uacb0 \ud55c \uac00\uc9c0\ub294 \ud589\uac04 \uc0ac\uc774\uc5d0 \uc228\uc5b4 \uc788\ub294 \uadf8 \ubb34\uc5c7\uc744 \uc774\ud574\ud55c\ub2e4\ub294 \uac83\uc774\ub2e4. \uadf8\ub4e4\uc740 \uc704\ud5d8\uc5d0 \uc775\uc219\ud558\uba70 \ubd80\uc640 \ud30c\uc0b0 \uc0ac\uc774\ub97c \uc808\ubb18\ud558\uac8c \uc624\uac04\ub2e4.\n\n> \uc544\ubb34 \uc0dd\uac01 \uc548 \ud558\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \ub04a\uc784\uc5c6\uc774 \uc0dd\uac01\ud55c\ub2e4.  \n> **\ud22c\uc790\uc5d0 \uc788\uc5b4\uc11c \uc911\uc694\ud55c \uac83\uc740 \uc9c0\uc2dd\uc774 \uc544\ub2c8\ub77c \uc0dd\uac01\uc774\ub2e4.**\n\n\uc778\uc0dd\uc5d0 \uc788\uc5b4\uc11c \ub450 \ubc88 \uc774\uc0c1 \ud30c\uc0b0\uc744 \uacbd\ud5d8\ud574\uc57c \uc9c4\uc815\ud55c \ud22c\uc790\uc790\ub77c\uace0 \ud560 \uc218 \uc788\ub2e4. \uc190\uc2e4\uc740 \uacbd\ud5d8\uc0c1\uc73c\ub85c \ubcf4\uba74 \uc218\uc775\uc774\ub2e4. **\uc2e4\ud328\uc5d0 \ub300\ud55c \uc9c4\uc9c0\ud55c \ubd84\uc11d\ub9cc\uc774 \uc131\uacf5\uc801\uc778 \ud22c\uc790\uc790\uac00 \ub418\ub294 \uc720\uc77c\ud55c \ubc29\ubc95\uc774\ub2e4.**\n\n\ub2e8\uae30 \ud22c\uc790\uc790\uc640 \uc7a5\uae30 \ud22c\uc790\uc790, \uc21c\uc885 \ud22c\uc790\uc790\uc758 \uacb0\uc815\uc801 \ucc28\uc774\ub294 \ubb34\uc5c7\uc778\uac00? \uc790\uc2e0\ub9cc\uc758 \uae30\uc900, \uc790\uc2e0\ub9cc\uc758 \uc2a4\ud0c0\uc77c, **\uc790\uc2e0\ub9cc\uc758 \uc0dd\uac01**\uc774\ub2e4. \uadf8\uac83\uc774 \uc633\ub4e0 \uadf8\ub974\ub4e0 \uc0c1\uad00\uc5c6\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 13\n\n**\uac00\uc7a5 \ud070 \ud22c\uc790\uc758 \ub300\uc0c1\uc740 \uc5ed\uc2dc \uc8fc\uc2dd\uc774\ub2e4.** \uc5b4\ub514\uc11c\ub4e0 \uc800\ud3c9\uac00 \uae30\uc5c5\uc744 \ubc1c\uacac\ud560 \uc218 \uc788\uc73c\uba70, \uc8fc\uc2dd\uc740 \uc7a5\uae30\uc801\uc73c\ub85c \uc6b0\uc0c1\ud5a5\ud55c\ub2e4. \uc790\uc2e0\uc758 \uc7ac\uc0b0\uc744 \uc57d\uac04 \ubd84\uc0b0\uc2dc\ud0a4\uace0 \ud06c\uace0 \ud2bc\ud2bc\ud55c \uae30\uc5c5\uc758 \uc8fc\uc2dd\uc5d0 \ud22c\uc790\ud55c\ub2e4\uba74 \uc131\uacf5 \uac00\ub2a5\uc131\uc744 \ud0a4\uc6b8 \uc218 \uc788\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 14\n\n**\uc8fc\uc2dd\uc2dc\uc7a5\uc740 \uc790\ubcf8\uc8fc\uc758 \uacbd\uc81c\uc758 \uc911\ucd94\uc2e0\uacbd\uc774\uba70 \ub3d9\ub825\uc774\ub2e4.** \uc6b0\ub9ac\ub294 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uae30\ubcf8 \uba5c\ub85c\ub514\ub97c \uc54c\uc544\ub4e4\uc744 \uc218 \uc788\ub294 \uc548\ud14c\ub098\ub97c \uac00\uc9c0\uace0 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc774 \uae30\ubcf8 \uba5c\ub85c\ub514\ub9cc \uc54c\uc544\ub4e4\uc744 \uc218 \uc788\ub2e4\uba74 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0\uc11c \ub3c8\uc744 \ubc84\ub294 \uac83\uc774 \uadf8\ub807\uac8c \uc5b4\ub835\uc9c0 \uc54a\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 15\n\n\ud22c\uc790\uc790\ub294 \ub0b4\uc77c\uc774 \uc5b4\ub5a8\uc9c0 \uc54c\uc9c0 \ubabb\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub298 \uadf8\ub9ac\uace0 \uc5b4\uc81c\uac00 \uc5b4\ub5a0\ud588\ub294\uc9c0 \uc798 \uc54c\uace0 \uc788\ub2e4. **\uc774\uac83\uc740 \uc0ac\uc2e4 \uc0c1\ub2f9\ud788 \uc911\uc694\ud55c \uac83\uc774\ub2e4. \uc65c\ub0d0\ud558\uba74 \ub300\ubd80\ubd84 \uc0ac\ub78c\ub4e4\uc740 \uadf8\uac83\uc870\ucc28 \ubaa8\ub974\uae30 \ub54c\ubb38\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 16\n\n**\uacbd\uc81c\uc640 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uad00\uacc4: \uac1c\uc640 \uc8fc\uc778** \u2014 \uc774 \ube44\uc720\ub294 \uc808\ubb18\ud558\ub2e4.\n\n\ud55c \ub0a8\uc790\uac00 \uac1c\ub97c \ub370\ub9ac\uace0 \uc0b0\ucc45\uc744 \ud55c\ub2e4. \uac1c\ub294 \uc8fc\uc778\ubcf4\ub2e4 \uc55e\uc11c \ub2ec\ub824\uac00\ub2e4\uac00 \uc8fc\uc778\uc744 \ub3cc\uc544\ubcf8\ub2e4. \uadf8\ub9ac\uace0 \ub2e4\uc2dc \uc55e\uc73c\ub85c \ub2ec\ub824\uac00\ub2e4\uac00, \uc790\uae30\uac00 \uc8fc\uc778\ubcf4\ub2e4 \ub108\ubb34 \ub9ce\uc774 \uc55e\uc11c \uc654\uc74c\uc744 \ubcf4\uace4 \ub2e4\uc2dc \uc8fc\uc778\uc5d0\uac8c\ub85c \ub3cc\uc544\uac04\ub2e4. \uadf8\ub807\uac8c \ub458\uc740 \uc0b0\ucc45\uc744 \ud558\uba74\uc11c \ubaa9\ud45c\uc5d0 \ub3c4\ub2ec\ud558\uac8c \ub41c\ub2e4. **\uc8fc\uc778\uc774 1km\ub97c \uac77\ub294 \ub3d9\uc548 \uac1c\ub294 \uc55e\uc11c\uac14\ub2e4 \ub3cc\uc544\uc624\uae30\ub97c \ubc18\ubcf5\ud558\uba74\uc11c 4km\ub97c \uac77\uac8c \ub41c\ub2e4.**\n\n\uc5ec\uae30\uc11c \uc8fc\uc778\uc740 \uacbd\uc81c\uc774\uace0, \uac1c\ub294 \uc8fc\uc2dd\uc2dc\uc7a5\uc774\ub2e4. **\uacbd\uc81c\ub294 \uc9c0\uc18d\uc801\uc73c\ub85c \ubc1c\uc804\ud558\uc9c0\ub9cc \ud55c\ub450 \uac78\uc74c \uba48\ucd94\uae30\ub3c4 \ud558\uace0 \ub4b7\uac78\uc74c\uc9c8 \uce58\uae30\ub3c4 \ud55c\ub2e4.** \ubb3c\ub860 \uadf8 \uc0ac\uc774\uc5d0 \uc8fc\uc2dd\uc2dc\uc7a5\uc740 \uc218\ubc31 \ubc88\ub3c4 \uc804\uc9c4\ud558\uace0 \ud6c4\ud1f4\ud55c\ub2e4. \uc7a5\uae30\uc801\uc73c\ub85c\ub294 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c, \uadf8\ub7ec\ub098 \ub2e8\uae30\uc801\uc73c\ub85c\ub294 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uac04\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 17\n\n\uc560\ub110\ub9ac\uc2a4\ud2b8\ub4e4\uc740 \ub9e4\uc77c \uc5f4\uc2ec\ud788 \uc2dc\uc138 \ubcc0\ub3d9\uc744 \ubd84\uc11d\ud558\uace0 \uc124\uba85\ud55c\ub2e4. \uc8fc\uc2dd\uc758 \uc0c1\uc2b9\uc774\ub098 \ud558\ub77d\uc744 \uc124\uba85\ud558\ub294 \ub17c\ub9ac\ub294 \ub108\ubb34\ub098\ub3c4 \ub9ce\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub7f0 \ubd84\uc11d\uc740 \ud22c\uc790\uc790\ub4e4\uc5d0\uac8c \ub3c4\uc6c0\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4. \uc804\ubb38\uac00\ub4e4\uc740 \uc5b4\ub5bb\uac8c\ub4e0 \ub17c\ub9ac\uc801 \uc774\uc720\ub97c \ucc3e\uc73c\ub824 \ud558\uc9c0\ub9cc **\uc8fc\uc2dd\uc2dc\uc7a5\uc740 \ub098\ub984\uc758 \uace0\uc720 \ub17c\ub9ac\uac00 \uc788\ub2e4.**\n\n> \ub098\ub294 \uc774\ub807\uac8c \uc81c\uc548\ud558\uace0 \uc2f6\ub2e4: **\uc8fc\uc2dd\uc2dc\uc7a5\uc758 \ubcc0\ub3d9\uc5d0 \ub300\ud574 \ud56d\uc0c1 \ub0c9\uc815\ud568\uc744 \uc720\uc9c0\ud558\uace0, \uc65c \uc774\ub807\uac8c \ubcc0\ub355\uc2a4\ub7ec\uc6b4\uc9c0\uc5d0 \ub300\ud574 \uc5b4\ub5a4 \ub17c\ub9ac\uc801 \uc124\uba85\ub3c4 \ucc3e\uc73c\ub824 \ud558\uc9c0 \ub9d0\ub77c.**\n\n---\n\n## \ud3ec\uc778\ud2b8 18\n\n**\uc8fc\uc2dd\uc2dc\uc7a5\uc744 \uc9c0\ubc30\ud558\ub294 \uc720\uc77c\ud55c \ub17c\ub9ac: \uacf5\uae09\uacfc \uc218\uc694\uc758 \ubc95\uce59.**\n\n- \uc8fc\uc2dd\uc758 \uacf5\uae09\uc774 \uc218\uc694\ubcf4\ub2e4 \ub9ce\uc73c\uba74 \uc8fc\uac00\ub294 \ub5a8\uc5b4\uc9c4\ub2e4.\n- \uc8fc\uc2dd\uc758 \uc218\uc694\uac00 \uacf5\uae09\ubcf4\ub2e4 \ub9ce\uc73c\uba74 \uc8fc\uac00\ub294 \uc62c\ub77c\uac04\ub2e4.\n- \uc218\uc694\uc640 \uacf5\uae09\uc774 \uc11c\ub85c \ub9de\uc544\ub5a8\uc5b4\uc9c4\ub2e4\uba74 \uc8fc\uac00\ub294 \ubcc4\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 19\n\n**\uc8fc\uac00\uc758 \ud750\ub984\uc740 \ub9e4\ub3c4\uc790\uac00 \ub9e4\uc218\uc790\ubcf4\ub2e4 \ub354 \uae09\ubc15\ud568\uc744 \ub290\ub07c\ub294\uac00 \uc544\ub2cc\uac00\uc5d0 \ub2ec\ub824 \uc788\ub2e4.**\n\n- \uc8fc\uc2dd\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \uc2ec\ub9ac\uc801\u00b7\ubb3c\uc9c8\uc801 \uc555\ubc15\uac10\uc73c\ub85c \uc8fc\uc2dd\uc744 \ub0b4\ub193\uc558\ub294\ub370, \ub3c8\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \uc0b4 \ub9c8\uc74c\uc740 \uc788\uc73c\ub098 \uaf2d \uc0ac\uc57c \ud55c\ub2e4\ub294 \uc555\ubc15\uac10\uc774 \uc5c6\ub2e4\uba74 \uc8fc\uac00\ub294 \ub5a8\uc5b4\uc9c4\ub2e4.\n- \ubc18\ub300\ub85c \ub3c8\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \uae09\ud558\uac8c \uc8fc\uc2dd\uc744 \ucc3e\uace0, \uc8fc\uc2dd\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \uadf8\ub2e4\uc9c0 \ud314\uc544\uc57c \ud558\ub294 \uc555\ubc15\uac10\uc774 \uc5c6\ub2e4\uba74 \uc8fc\uac00\ub294 \uc0c1\uc2b9\ud55c\ub2e4.\n\n> **\ub098\ub294 \uc774 \uac00\ub974\uce68\uc744 \uc78a\uc5b4 \ubcf8 \uc801\uc774 \uc5c6\ub2e4. \ubaa8\ub4e0 \uac83\uc740 \uacf5\uae09\uacfc \uc218\uc694\uc5d0 \ub2ec\ub824 \uc788\ub2e4. \ub0b4 \ubaa8\ub4e0 \uc8fc\uc2dd\ud22c\uc790 \uc774\ub860\uc740 \uc5ec\uae30\uc5d0\uc11c \uc138\uc6cc\uc84c\ub2e4\uace0 \ud574\ub3c4 \uacfc\uc5b8\uc774 \uc544\ub2c8\ub2e4.**\n\n\uadf8 \uc5b4\ub5a0\ud55c \uc678\ubd80 \uc694\uc778\ub3c4 \uacf5\uae09\uacfc \uc218\uc694\uc758 \ub17c\ub9ac \uc55e\uc5d0\uc11c\ub294 \uc791\uc544\uc9c4\ub2e4. \uc774 \ub17c\ub9ac\ub97c \uc774\ud574\ud558\ub294 \uc21c\uac04 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0\uc11c \uc5b8\uc81c \ub9e4\uc218\ud558\uace0 \uc5b8\uc81c \ub9e4\ub3c4\ud574\uc57c \ud558\ub294\uc9c0 \uc27d\uac8c \uc54c \uc218 \uc788\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 20\n\n**\uc8fc\uc2dd\uc2dc\uc7a5\uc744 \uacb0\uc815\ud558\ub294 \uc7a5\uae30\uc801 \uba5c\ub85c\ub514: \uc804\uc7c1\uacfc \ud3c9\ud654.** \ud3c9\ud654\uac00 \uc720\uc9c0\ub41c\ub2e4\uba74 \uacbd\uc81c\ub294 \uc7a5\uae30\uc801\uc73c\ub85c \ubc1c\uc804\ud558\uba70 \uc8fc\uc2dd\uc2dc\uc7a5\uc740 \uc6b0\uc0c1\ud5a5\ud55c\ub2e4.\n\n> \uc131\uacf5\ud558\ub824\uba74 \uc6b0\ub7c9\uc8fc\uc5d0 \ud22c\uc790\ud55c \ub4a4 \uc218\uba74\uc81c\ub97c \uba39\uace0 \uba87 \ub144 \ub3d9\uc548 \uc7a0\ub4e4\uc5b4 \uc788\uc73c\uba74 \ub41c\ub2e4. \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uc6c0\uc9c1\uc784\uc744 \ub4e3\uac70\ub098 \ubcf4\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uacb0\uad6d \uc6b0\uc0c1\ud5a5\ud558\uac8c \ub420 \uac83\uc774\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 21\n\n**\uc8fc\uc2dd\uc2dc\uc7a5\uc744 \uacb0\uc815\ud558\ub294 \uc911\uae30\uc801 \uba5c\ub85c\ub514: \ub3c8\uacfc \uc2ec\ub9ac.**\n\n> \ub3c8 + \uc2ec\ub9ac\uac00 \ucd94\uc138\ub97c \ub9cc\ub4e4\uc5b4\ub0b8\ub2e4.\n\n\ud06c\uace0 \uc791\uc740 \ud22c\uc790\uc790\uac00 \uc8fc\uc2dd\uc744 \uc0ac\ub824 \ud558\uace0 \ub610 \uc0b4 \uc218 \uc788\uc73c\uba70, \uc2dc\uc138\ub294 \uc0c1\uc2b9\ud55c\ub2e4. \uacbd\uc81c \uc0c1\ud669\uc774 \ub099\uad00\uc801\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uace0 \uc8fc\uba38\ub2c8\uc640 \uae08\uace0\uc5d0 \ucda9\ubd84\ud55c \uc720\ub3d9 \uc790\uae08\uc774 \uc788\ub2e4\uba74, \uc774\uac83\uc774 \uac15\uc138\uc7a5\uc774 \ud615\uc131\ub418\ub294 \ube44\ubc00\uc774\ub2e4. \uc5ec\ub860\uc774 \ube44\ud310\uc801\uc774\uace0 \uc804\ub9dd\uc774 \ubd88\ud22c\uba85\ud558\uace0 \ubd80\ub3d9\uc0b0\uc774\ub098 \ub192\uc740 \uc774\uc790\uc758 \uc608\uae08\u00b7\ucc44\uad8c\uc5d0 \uc790\uae08\uc774 \uc3e0\ub824 \uc5ec\uc720 \uc790\uae08\uc774 \uc5c6\uc73c\uba74 \uc8fc\uac00\ub294 \ub5a8\uc5b4\uc9c4\ub2e4.\n\n**80\ub144 \uacbd\ud5d8\uc758 \ud575\uc2ec:**\n\n> \ub0b4 \uacbd\ud5d8\uc0c1, \ub3c8\uc774 \ub108\ubb34 \ub118\uccd0 \ud750\ub974\uba70 \uc8fc\uc2dd\uc5d0 \ub300\ud574 \ubd80\uc815\uc801\uc778 \uc0dd\uac01\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4 \ud558\ub354\ub77c\ub3c4 \uc774 \uc720\ub3d9 \uc790\uae08\uc740 \ub2a6\uc5b4\ub3c4 9~12\uac1c\uc6d4 \uc0ac\uc774\uc5d0 \uc8fc\uc2dd\uc2dc\uc7a5\uc73c\ub85c \ub4e4\uc5b4\uc628\ub2e4.\n\n\uc774\ub54c \uccab \ubc88\uc9f8 \ub9e4\uc218\ub294 \uc644\uc804\ud788 \ubc14\ub2e5\uc5d0\uc11c \uc2dc\uc791\ud558\uba70, \uc2dc\uc138\ub294 \uc11c\uc11c\ud788 \uc62c\ub77c\uac00\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc8fc\uac00\uac00 \uc624\ub974\uba74 \ub2e4\uc2dc \ub300\uc911\uc758 \uad00\uc2ec\uc744 \ubc1b\uac8c \ub418\uc5b4 \uc8fc\uc2dd\uc744 \uc0ac\uace0, \uadf8\ub7ec\uba74 \uc774\uac83\uc774 \uc0c8\ub85c\uc6b4 \ub9e4\uc218\uc790\ub97c \uc790\uadf9\ud55c\ub2e4. \ubd84\uc11d\uac00\ub4e4\uc740 \uc0c1\uc2b9 \uc694\uc778\uc744 \ub099\uad00\uc801\uc778 \uacbd\uae30\ub77c\uace0 \ubd84\uc11d\ud558\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc2e4\uc81c\ub85c \uacbd\uae30\uac00 \ub099\uad00\uc801\uc774\uc9c0 \uc54a\uc544\ub3c4 \ub9d0\uc774\ub2e4. \uc774\ub7ec\ud55c \uae0d\uc815\uc801 \ub17c\ud3c9\uc5d0 \ud798\uc785\uc5b4 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\uac01\uc740 \ubc14\ub00c\uace0, \uc11c\uc11c\ud788 \uc8fc\uc2dd\uc2dc\uc7a5\uc73c\ub85c \uc790\uae08\uc774 \ud758\ub7ec\ub4e4\uc5b4 \uc628\ub2e4. \uadf8 \uacb0\uacfc \uc8fc\uac00\ub294 \ub610 \uc62c\ub77c\uac04\ub2e4.\n\n\ubc18\ub300\uc758 \uacbd\uc6b0\ub3c4 \ub611\uac19\ub2e4. **\ub3c8\uc774 \ubd80\uc871\ud558\ub2e4\uba74 \ud22c\uc790 \uc2ec\ub9ac\ub294 \uadf8\ub85c\ubd80\ud130 9~12\uac1c\uc6d4 \ud6c4\uc5d0\ub294 \ubd80\uc815\uc801\uc73c\ub85c \ubcc0\ud55c\ub2e4.** \uc544\ubb34\ub9ac \uc88b\uc740 \uacbd\uc81c \uc18c\uc2dd\uc774 \ub9ce\ub2e4 \ud574\ub3c4 \uc790\uae08\uc774 \uc0c8\ub85c \uc720\uc785\ub418\uc9c0 \uc54a\ub294\ub2e4\uba74 \uc8fc\uac00\ub294 \uc624\ub974\uc9c0 \uc54a\ub294\ub2e4. \ud22c\uc790\uc790\ub294 \uae30\ub300\ud55c \ub9cc\ud07c \uc8fc\uac00\uac00 \uc624\ub974\uc9c0 \uc54a\uc73c\uba74 \uae08\uc138 \uc2e4\ub9dd\ud574 \uc8fc\uc2dd\uc2dc\uc7a5\uc744 \ube60\uc838\ub098\uc624\ub824 \ud55c\ub2e4. \uccab \ubc88\uc9f8 \ub9e4\ub3c4\ub294 \uc2dc\uc138\ub97c \ud558\ub77d\uc2dc\ud0a4\uace0, \uc774\uac83\uc774 \uacc4\uc18d \ucd94\uac00 \ub9e4\ub3c4\ub97c \ubd80\ucd94\uae34\ub2e4. \uc2dc\uc7a5 \ube44\ud3c9\uac00\ub4e4\uc740 \uc2dc\uc138 \ud558\ub77d\uc758 \uadfc\uac70\ub97c \uc5b4\ub5bb\uac8c\ub4e0 \ucc3e\uc544\uc11c \uc545\uc7ac \uc18c\uc2dd\uc744 \uc591\uc0b0\ud55c\ub2e4.\n\n**\uc989, \ub3c8\uc758 \uc720\ubb34\uc5d0 \ub530\ub77c\uc11c \uc8fc\uc2dd\uc2dc\uc7a5\uc774 \uc6c0\uc9c1\uc774\ub294 \uac83\uc774\uc9c0, \uacbd\uae30 \uc804\ub9dd\uc5d0 \uc758\ud574\uc11c \uc8fc\uc2dd\uc2dc\uc7a5\uc774 \uc6c0\uc9c1\uc774\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4.** \ub3c8\uc774 \uba3c\uc800\uace0 \uadf8 \ub2e4\uc74c \uacbd\uae30 \uc804\ub9dd\uc774 \ub098\uc624\ub294 \uac83\uc774\uc9c0, \uacbd\uae30 \uc804\ub9dd\uc774 \ub098\uc624\uace0 \ub3c8\uc774 \ub098\uc624\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 21(\ubcf4\ucda9)\n\n**\uacbd\uae30\ub294 \uc911\uae30\uc801\uc73c\ub85c \uc8fc\uac00\uc640 \ubb34\uad00\ud558\ub2e4.**\n\n\ud638\uacbd\uae30\uc5d0 \ub4e4\uc5b4\uc11c\uba70 \uae30\uc5c5\uc740 \uc790\uae08\uc744 \uc9c1\uc811 \uc2dc\uc124\ud22c\uc790\uc5d0 \ud65c\uc6a9\ud558\uc5ec \uc99d\uac00\ud558\ub294 \uc218\uc694\ub97c \ucda9\uc871\ud558\uace0\uc790 \ud55c\ub2e4. \uae30\uc5c5\uc740 \uc0c8\ub85c\uc6b4 \uc790\uae08\uc774 \ud544\uc694\ud558\uba70 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \ub300\ud55c \uc758\uc874\ub3c4\ub97c \ub192\uc778\ub2e4. \uadf8 \uacb0\uacfc \uc8fc\uc2dd \uc218\ub294 \ub9ce\uc544\uc9c0\uace0 \uacf5\uae09\uc774 \ub298\uc5b4\ub09c\ub2e4. \ub9ce\uc740 \ud68c\uc0ac\ub4e4\uc774 \uc790\uae08\uc744 \ub9c8\ub828\ud558\uae30 \uc704\ud574 \ubcf4\uc720\ud558\uace0 \uc788\ub294 \ub2e4\ub978 \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc744 \ud310\ub2e4. **\ub530\ub77c\uc11c \ud638\uacbd\uae30\uc5d0\ub3c4 \uc8fc\uc2dd\uc758 \uacf5\uae09 \uacfc\uc789\uc73c\ub85c \uc8fc\uac00\ub294 \ud558\ub77d\ud560 \uc218 \uc788\ub2e4.**\n\n\ubd88\uacbd\uae30\uc5d0 \ub4e4\uc5b4\uc11c\ub294 \uae30\uc5c5\uc740 \uc790\uae08\uc744 \uc2dc\uc124\ud22c\uc790\uc5d0 \ud65c\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub0a8\ub294 \uc790\uae08\uc774 \uc788\ub2e4\uba74 \uad73\uc774 \uc2dc\uc124\ud22c\uc790\ub97c \ud558\uc9c0 \uc54a\uace0 \uc8fc\uc8fc\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud574 \uc790\uc0ac\uc8fc\ub97c \ub9e4\uc785\ud558\uc5ec \uc18c\uac01\ud55c\ub2e4. \uc8fc\uc2dd\uc758 \uacf5\uae09\uc740 \uc904\uc5b4\ub4e0\ub2e4. \ubd88\uacbd\uae30\uc5d0 \uc0ac\ub78c\ub4e4\uc740 \uc18c\ube44\ub97c \uc904\uc774\uace0 \uc800\ucd95\uc744 \ub298\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uc800\ucd95\uc561\uc740 \uacb0\uad6d \uc8fc\uc2dd\uc2dc\uc7a5\uc73c\ub85c \ud758\ub7ec\ub4e4\uc5b4 \uc628\ub2e4. \uc989 \uc8fc\uc2dd\uc758 \uc218\uc694\ub294 \uc99d\uac00\ud55c\ub2e4. **\ub530\ub77c\uc11c \ubd88\uacbd\uae30\uc5d0\ub3c4 \uc8fc\uc2dd\uc758 \uc218\uc694 \uc99d\uac00\ub85c \uc8fc\uac00\ub294 \uc0c1\uc2b9\ud560 \uc218 \uc788\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 22\n\n**\uc778\ud50c\ub808\uc774\uc158\uc5d0 \ub300\ud56d\ud558\ub294 \uc2f8\uc6c0\uc740 \ud574\ub85c\uc6b8 \ubfd0\uc774\ub2e4.** \uc99d\uad8c\uc778\ub4e4\uc740 \uc778\ud50c\ub808\uc774\uc158\uc744 \uadf9\ub3c4\ub85c \uc2eb\uc5b4\ud55c\ub2e4. \ud558\uc9c0\ub9cc \uc778\ud50c\ub808\uc774\uc158\uc740 \uc8fc\uc2dd\uc5d0 \uc5b4\ub5a0\ud55c \ubd80\uc815\uc801 \uc601\ud5a5\ub3c4 \ub07c\uce58\uc9c0 \uc54a\ub294\ub2e4. **\uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \ubd80\uc815\uc801 \uc601\ud5a5\uc744 \ub07c\uce58\ub294 \uac83\uc740 \uc778\ud50c\ub808\uc774\uc158\uc744 \ub9c9\uae30 \uc704\ud574 \ucde8\ud558\ub294 \uc911\uc559\uc740\ud589\uc758 \uc870\uce58\ub2e4.** \uc989, \uc778\ud50c\ub808\uc774\uc158\uc774 \uc544\ub2c8\ub77c \uace0\uae08\ub9ac \uc815\ucc45\uc774 \uc8fc\uc2dd\uc2dc\uc7a5\uc744 \ud574\uce58\ub294 \uc694\uc778\uc774\ub2e4.\n\n\uc778\ud50c\ub808\uc774\uc158\uc758 \uc9c4\ud589 \uacfc\uc815:\n\n1. \ud638\ud669\uc774 \uacc4\uc18d\ub418\uba74 \uc81c\ud488\uacfc \uc11c\ube44\uc2a4\uc758 \uc218\uc694\uac00 \uc99d\uac00\ud55c\ub2e4\n2. \uc81c\ud488\uacfc \uc11c\ube44\uc2a4\uc758 \uac00\uaca9\uc774 \uc0c1\uc2b9\ud55c\ub2e4\n3. \uc6d0\uc790\uc7ac \uac00\uaca9\uc774 \uc0c1\uc2b9\ud55c\ub2e4\n4. \ubb3c\uac00\uac00 \uc0c1\uc2b9\ud55c\ub2e4\n5. \uc0dd\uacc4\ube44\uac00 \uc0c1\uc2b9\ud558\uc5ec \ub178\uc870\uc5d0\uc11c \uc784\uae08 \uc0c1\uc2b9\uc744 \uc694\uad6c\ud55c\ub2e4\n6. \uc784\uae08\uc774 \uc0c1\uc2b9\ud558\uba74 \uc0dd\uc0b0 \uc6d0\uac00\uac00 \uc0c1\uc2b9\ud558\uace0, \uacb0\uad6d \uc81c\ud488\u00b7\uc11c\ube44\uc2a4 \uac00\uaca9\uc774 \ub2e4\uc2dc \uc0c1\uc2b9\ud55c\ub2e4\n7. \uc774 \uacfc\uc815\uc774 \ubc18\ubcf5\ub418\uba74\uc11c \uc778\ud50c\ub808\uc774\uc158\uc774 \ubc1c\uc0dd\ud55c\ub2e4\n\n\uc778\ud50c\ub808\uc774\uc158\uc740 \uacb0\uad6d \ubb3c\uac00 \uc0c1\uc2b9\uc744 \ubc1c\uc0dd\uc2dc\ud0a4\ub294 \uac83\uc774\uc9c0, \uc8fc\uac00\uc5d0 \uc9c1\uc811 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud654\ud3d0\uac00\uce58\uac00 \ud558\ub77d\ud558\uba74 \uc0ac\ub78c\ub4e4\uc740 \ub3c8\uc744 \uae08\u00b7\uace8\ub3d9\ud488 \ub4f1\uc73c\ub85c \uad50\ud658\ud574\uc11c \uc790\uc0b0\uc744 \ubcf4\ud638\ud558\ub824 \ud55c\ub2e4. \uadf8\ub7ec\uba74 \uc790\ubcf8\uc2dc\uc7a5\uc5d0\uc11c \ub3c8\uc774 \ube60\uc838\ub098\uac04\ub2e4. \ud22c\uc790\ud560 \ub3c8\uc774 \uc5c6\uc73c\uba74 \ub300\ub7c9 \uc2e4\uc5c5\uacfc \uacbd\uc81c\uc704\uae30\uac00 \ubc1c\uc0dd\ud55c\ub2e4. **\uc989, \uc778\ud50c\ub808\uc774\uc158\uc740 \uc790\ubcf8\uc2dc\uc7a5\uc5d0\uc11c \ub3c8\uc774 \ube60\uc838\ub098\uac00\ub294 \ub370 \uc9c1\uc811\uc801 \uc601\ud5a5\uc774 \uc788\ub294 \uac83\uc774\uc9c0, \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \uc9c1\uc811\uc801 \uc601\ud5a5\uc744 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.** \uc704\uae30\ub97c \ub9c9\uae30 \uc704\ud574 \uc815\ubd80\uc640 \uc911\uc559\uc740\ud589\uc774 \uc870\uce58\ub97c \ucde8\ud558\uba70, \uadf8 \uc870\uce58\uc758 \uacb0\uacfc \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \uc9c1\uc811\uc801\uc73c\ub85c \uc601\ud5a5\uc744 \ubbf8\uce58\uac8c \ub41c\ub2e4. \uadf8 \ub300\ud45c\uc801\uc778 \uc870\uce58\uac00 \ubc14\ub85c \uae08\ub9ac \uc778\uc0c1\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 23\n\n\u2605 **\uc774 \uc601\uc0c1\uc758 \ud575\uc2ec \uc911 \ud575\uc2ec \u2014 \uae08\ub9ac\ub294 \uc8fc\uac00\uc5d0 \uac00\uc7a5 \ud070 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc694\uc18c** \u2605\n\n\uacbd\uae30\uac00 \uce68\uccb4\ub418\uba74 \uae08\ub9ac\ub97c \uc778\ud558\ud55c\ub2e4. \uae08\ub9ac\uac00 \uc778\ud558\ub418\uba74 \ub300\ucd9c\uc774 \uc6a9\uc774\ud574\uc9c0\uace0, \uc18c\ube44\uc790\ub4e4\uc774 \ub300\ucd9c\uc744 \ubc1b\uc544 \uc18c\ube44\uc7ac\ub97c \uad6c\uc785\ud55c\ub2e4. \uc18c\ube44\uc7ac\uc5d0 \ub300\ud55c \uc218\uc694\uac00 \uc99d\uac00\ud558\uace0, \uae30\uc5c5\ub4e4\uc740 \uadf8 \uc218\uc694\ub97c \ucda9\uc871\ud558\uace0\uc790 \ub300\ucd9c\uc744 \ubc1b\uc544 \uc124\ube44\ud22c\uc790\ub97c \uc9c4\ud589\ud55c\ub2e4.\n\n**\uae08\ub9ac \uc870\uce58\uac00 \uc131\uacf5\ud558\ub294 \uacbd\uc6b0:**\n\n> \uc8fc\uac00\uac00 \uae09\uaca9\ud788 \uc0c1\uc2b9\ud55c\ub2e4 \u2192 \uc778\ud50c\ub808\uc774\uc158 \uae30\ubbf8\uac00 \ubcf4\uc778\ub2e4 \u2192 \uae08\ub9ac\ub97c \uc5ec\ub7ec \ucc28\ub840 \uc778\uc0c1\ud55c\ub2e4 \u2192 \uc99d\uc2dc \ub300\ud3ed\ub77d \u2192 \uae08\ub9ac\ub97c \ub2e4\uc2dc \uc778\ud558\ud55c\ub2e4 \u2192 \uc8fc\uac00\ub294 \uc5bc\ub9c8 \uc9c0\ub098\uc9c0 \uc54a\uc544 \ub2e4\uc2dc \ucd5c\uace0\uc810\uc744 \uae30\ub85d\ud55c\ub2e4 \u2192 \ucd5c\uace0\uc810\uc744 \ucc0d\uc740 \uc774\ud6c4 \ub354\uc6b1 \ub9ce\uc774 \uc0c1\uc2b9\ud55c\ub2e4.\n\n**\uae08\ub9ac \uc778\uc0c1 \ud6c4 \ud3ed\ub77d\uc774 \uc624\uba70, \ub2e4\uc2dc \uae08\ub9ac\ub97c \uc778\ud558\ud588\uc744 \ub54c\uac00 \uc808\ud638\uc758 \uae30\ud68c\ub77c\ub294 \uac83\uc774\ub2e4.**\n\n**\uae08\ub9ac \uc870\uce58\uac00 \uc2e4\ud328\ud558\ub294 \uacbd\uc6b0:**\n\n> \uae08\ub9ac \uc778\uc0c1\uc744 \ud588\uc74c\uc5d0\ub3c4 \uc8fc\uac00\uac00 \uacc4\uc18d \uc0c1\uc2b9\ud55c\ub2e4 \u2192 \uc778\ud50c\ub808\uc774\uc158\uc774 \ud655\uc2e4\ud574\uc9c4\ub2e4 \u2192 \uacbd\uc81c \ud0dc \uc704\uae30\uac00 \uc628\ub2e4 \u2192 \uc815\ubd80\u00b7\uc911\uc559\uc740\ud589\uc5d0\uc11c \uae08\ub9ac\ub97c \ub300\ud3ed \uc778\uc0c1\ud55c\ub2e4 \u2192 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \uc554\ud751\uae30\uac00 \uc628\ub2e4 (\uc740\ud589 \uc608\uae08 \uae09\uc99d, \ud1b5\ud654\ub7c9 \uae09\uaca9\ud788 \uac10\uc18c) \u2192 \uc544\ubb34\ub9ac \uacbd\uae30 \ud750\ub984\uc774 \uc88b\uc544\uc9c0\ub354\ub77c\ub3c4 \uc8fc\uac00\ub294 \uacc4\uc18d \ud558\ub77d\ud55c\ub2e4 \u2192 \uae08\ub9ac\ub97c \uc778\ud558\ud558\uc9c0\ub9cc \uc18c\uc6a9\uc5c6\ub2e4 (\uc784\uae08\u00b7\uac00\uaca9\uc774 \uc774\ubbf8 \uc624\ub97c \ub300\ub85c \uc62c\ub790\ub2e4) \u2192 \uc8fc\uac00\ub294 \uc7a5\uae30\uc801\uc73c\ub85c \ud558\ub77d\ud558\uace0 \uacbd\uae30 \uc704\uae30\uac00 \uc545\ud654\ub41c\ub2e4.\n\n**\uc131\uacf5\ud558\ub4e0 \uc2e4\ud328\ud558\ub4e0 \uacb0\uad6d \ud3ed\ub77d\uc7a5\uc740 \ubc18\ub4dc\uc2dc \uc628\ub2e4.** \ud3ed\ub77d\ud588\uc744 \ub54c \ud22c\uc790\ud558\uace0, \uc870\uce58\uac00 \uc2e4\ud328\ud55c \uacbd\uc6b0\ub77c\uba74 \ubc14\ub2e5\ubd80\ud130 \uae30\ub2e4\ub9ac\uba74 \ub41c\ub2e4.\n\n---\n\n**\uc815\ub9ac (\ubc1b\uc544 \uc801\uc744 \uac83):**\n\n> **\uae08\ub9ac\uac00 \uc8fc\uac00\uc5d0 \uac00\uc7a5 \ud070 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc694\uc18c\uc774\ubbc0\ub85c, \uc800\uc790\ub294 \uc7ac\ubb34\uc81c\ud45c \ub4f1 \uacf5\uc2dc\uc5d0 \uadf8\ub807\uac8c \uc8fc\ubaa9\ud558\uc9c0 \uc54a\ub294\ub2e4.** \uacf5\uc2dc\ub294 \uacb0\uad6d \uacfc\uac70\uc758 \uc0ac\uc2e4\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. **\uc911\uc559\uc740\ud589\uc774 \uae08\ub9ac\ub97c \uc778\uc0c1\ud558\uba74 \uc8fc\uac00\uac00 \ud558\ub77d\ud558\ub294 \uac83\uc740 \uc2dc\uac04 \ubb38\uc81c\uc774\ub2e4.** \ub9cc\uc57d \uc774\uc804\uc5d0 \uc8fc\uc2dd\uc2dc\uc7a5 \ubd84\uc704\uae30\uac00 \uacfc\uc5f4\ub418\uc5b4 \uc788\uc5c8\ub2e4\uba74 \uadf8\ub9cc\ud07c \ub5a8\uc5b4\uc9c0\ub294 \ud3ed\uc774 \ud06c\ub2e4. \uc774 \ucc28\uc774\ub97c \uc544\ub294 \uc0ac\ub78c\uc740 \uc801\uc2dc\uc5d0 \ube60\uc838\ub098\uc62c \uc218 \uc788\ub2e4. **\uc8fc\uac00\uac00 \ubc14\ub2e5\uc77c \ub54c \uc2dc\uc7a5\uc5d0 \ub4e4\uc5b4\uc628 \ud22c\uc790\uc790\ub294 \ud070 \ubd80\ub97c \ucd95\uc801\ud560 \uc218 \uc788\ub2e4.**\n\n\ubbf8\uad6d \uc0ac\ub840: \uc5f0\uc900\uc5d0\uc11c \uae08\ub9ac\ub97c \uc5ec\ub7ec \ucc28\ub840 \uc778\uc0c1\ud588\uc74c\uc5d0\ub3c4 \uc8fc\uac00\ub294 \uae30\ub85d\uc744 \uacbd\uc2e0\ud558\uba70 \uc0c1\uc2b9\ud588\ub2e4. \uadf8\ub7ec\ub2e4 \uacb0\uad6d 8\uc6d4\uc5d0 \uace0\uc810\uc744 \ucc0d\uc740 \uc8fc\uac00\ub294 10\uc6d4\uc5d0 \ub300\ud3ed\ub77d\ud588\ub2e4. \uae08\ub9ac\ub97c \uc778\ud558\ud558\uc790 \uc8fc\uac00\uc758 \ubc18\uc751\uc740 \ubbf8\ube44\ud588\uace0 \ub274\uc2a4\uc5d0\uc11c\ub294 \uc548 \uc88b\uc740 \uc18c\uc2dd\ub9cc \ubcf4\ub3c4\ub410\ub2e4. \ud558\uc9c0\ub9cc \uc800\uc790\ub294 \uc774\ub807\uac8c \ub9d0\ud55c\ub2e4: **\"\uae08\ub9ac\ub97c \uc778\ud558\ud588\ub2e4\uba74, '\uc5b8\uc81c\ub77c\ub358\uac00', '\uadf8\ub7ec\ub098'\ub77c\ub294 \ub9d0\uc740 \uc78a\uace0 \ubb34\uc870\uac74 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \ub6f0\uc5b4\ub4e4\uc5b4\uc57c \ud55c\ub2e4.\"** \uc774 \uc704 \uc0c1\ud669\uc740 \uacc4\uc18d \ubc18\ubcf5\ub41c\ub2e4. \uc774\uac83\uc740 \uc601\uc6d0\ubd88\ubcc0\uc758 \ubc95\uce59\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 24\n\n**\ubd80\ud654\ub1cc\ub3d9\ud30c vs. \uc18c\uc2e0\ud30c**\n\n\uc18c\uc2e0\ud30c\ub294 \ud22c\uc790\uc790\uc774\uba70 \uc7a5\uae30\uc801\uc73c\ub85c \uc2b9\uc790\uc5d0 \uc18d\ud55c\ub2e4. \ubd80\ud654\ub1cc\ub3d9\ud30c \ub355\ubd84\uc5d0 \uc18c\uc2e0\ud30c\ub294 \uc774\uc775\uc744 \uac70\ub454\ub2e4. \ubd80\ud654\ub1cc\ub3d9\ud30c\ub294 \uc8fc\uc2dd\uc73c\ub85c \ub3c4\ubc15\uc744 \ud558\ub294 \uc0ac\ub78c\ub4e4\uc774\ub2e4.\n\n- \ubd80\ud654\ub1cc\ub3d9\ud30c\ub294 \uc88b\uc740 \uc18c\uc2dd\uc5d0\ub294 \ubc18\uc751\ud558\uc9c0 \uc54a\uc9c0\ub9cc, \ub098\uc05c \uc18c\uc2dd\uc5d0\ub294 \ubbfc\uac10\ud558\uac8c \ubc18\uc751\ud55c\ub2e4.\n- \uc18c\uc2e0\ud30c\ub294 \uadf8 \ubc18\ub300\ub2e4. \uc88b\uc740 \uc18c\uc2dd\uc5d0 \ubc18\uc751\ud558\uba70 \ub098\uc05c \uc18c\uc2dd\uc5d0 \ubc18\uc751\ud558\uc9c0 \uc54a\ub294\ub2e4.\n\n**\uc18c\uc2e0\ud30c\uac00 \uac00\uc9c0\uace0 \uc788\ub294 4G: \ub3c8(Geld), \uc0dd\uac01(Gedanken), \uc778\ub0b4(Geduld), \ud589\uc6b4(Gl\u00fcck).**\n\n\ud380\ub4dc \ub9e4\ub2c8\uc800\uc640 \uae30\uad00 \ud22c\uc790\uc790\ub4e4\uc740 \ubd80\ud654\ub1cc\ub3d9 \ud22c\uc790\uc790\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uadf8\ub4e4\uc740 \uc0dd\uac01\ub3c4 \uc5c6\uace0 \uc778\ub0b4\ub3c4 \uc5c6\ub2e4. **\uc808\ub300 \ube5a\ub0b4\uc11c \ud22c\uc790\ud558\uc9c0 \ub9d0\uc790.** \uc800\uc790 \uc5ed\uc2dc \ube5a\uc744 \ub0b8 \ud22c\uc790\ub97c \ud55c \uc801\uc774 \uc788\uc73c\uba70, \uacb0\uacfc\ub294 \ud56d\uc0c1 \uc88b\uc9c0 \uc54a\uc558\ub2e4\uace0 \ud588\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 25\n\n**\uc0dd\uac01 \u2014 \uac00\uc7a5 \uc911\uc694\ud55c \ud22c\uc790\uc758 \uae30\ucd08**\n\n> \uc0dd\uac01\uc774 \uc633\uace0 \uadf8\ub974\ub4e0 \uc0c1\uad00\uc5c6\ub2e4. \uadf8\uac83\uc740 \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4. **\uc911\uc694\ud55c \uac83\uc740 \uc0dd\uac01\uc744 \ud558\uace0 \ub09c \ub4a4\uc5d0 \ub9e4\ub9e4\ub97c \ud574\uc57c \ud55c\ub2e4\ub294 \uac83\uc774\uba70, \uc0c1\uc0c1\ub825\uc744 \uac00\uc9c0\uace0 \uc788\uc5b4\uc57c \ud55c\ub2e4\ub294 \uac83\uc774\ub2e4.** \uadf8\ub9ac\uace0 \uc790\uc2e0\uc758 \uc0dd\uac01\uc744 \ubbff\uc5b4\uc57c \ud55c\ub2e4. \ub9cc\uc57d \ucda9\ubd84\ud788 \uc0dd\uac01\ud55c \ub05d\uc5d0 \uc5b4\ub5a4 \uc804\ub7b5\uc744 \uc138\uc6e0\ub2e4\uba74, \uce5c\uad6c\ub098 \uc77c\uc0c1 \uc0dd\ud65c\uc5d0 \ud754\ub4e4\ub824\uc11c\ub294 \uc548 \ub41c\ub2e4. \ud754\ub4e4\ub9ac\ub294 \uadf8 \uc21c\uac04 \uc0dd\uac01\uc740 \uc4f8\ubaa8\uc5c6\uac8c \ub41c\ub2e4.\n\n> **\uc798\ubabb\ub41c \uc790\uc2e0\uc758 \uc0dd\uac01\uc774\ub77c\ub3c4 \uc88b\uc73c\ub2c8 \uc2e0\ub150\uc744 \uac00\uc838\ub77c.**\n\n> \uc0c1\uc0c1\ub825\uc740 \uc9c0\uc2dd\ubcf4\ub2e4 \uc911\uc694\ud558\ub2e4. \u2014 \uc544\uc778\uc288\ud0c0\uc778\n\n\ud22c\uc790\uc790\uc758 \uc0c1\uc0c1\ub825\uc740 \uba40\ub9ac \ub0b4\ub2e4\ubcfc \uc218 \uc788\uac8c \ud574\uc900\ub2e4.\n\n**\ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 \uc2e4\uc81c \uc0ac\ub840:** \uc804\uc7c1\uc73c\ub85c \ud669\ud3d0\ud654\ub41c \uc774\ud0c8\ub9ac\uc544\uc5d0\uc11c \uc2e0\uae30\ud558\uac8c\ub3c4 \uacf5\uc7a5\ub4e4\uc740 \uac00\ub3d9\ud558\uc600\uc73c\ub098 \uc6d0\uc790\uc7ac\uac00 \uc5c6\uc5c8\ub2e4. \ubbf8\uad6d\uc740 \uc12c\uc720 \uc6d0\uc790\uc7ac\ub97c \uc870\ub2ec\ud574 \uc8fc\ub294 \ub300\uac00\ub85c \ubb3c\uac74\uc744 \uc2f8\uac8c \uacf5\uae09\ubc1b\uae30\ub85c \uc774\ud0c8\ub9ac\uc544\uc640 \ud569\uc758\ud588\ub2e4. \uc12c\uc720 \uc0b0\uc5c5\uc774 \ud65c\uc131\ud654\ub418\uc5c8\uace0, \uc800\uc790\ub294 \uc12c\uc720 \uc0b0\uc5c5\uc744 \uc9c1\uc811 \ub208\uc73c\ub85c \ud655\uc778\ud558\uc9c0 \uc54a\uc558\uc9c0\ub9cc \uc120\ub3c4 \ub9e4\uc218\ub85c \ud22c\uc790\ud574 \uc774\ubbf8 \uad6d\uac00\ub97c \ud615\uc131\ud558\uc600\ub2e4. \uc790\ub3d9\ucc28 \uc0b0\uc5c5\uc5d0\uc11c\ub3c4 \uac19\uc740 \uc6c0\uc9c1\uc784\uc774 \ubcf4\uc600\ub2e4. \uc774\ud0c8\ub9ac\uc544 \uc790\ub3d9\ucc28 \ud68c\uc0ac \ud53c\uc544\ud2b8\uac00 \ud654\uc81c\uc758 \uc885\ubaa9\uc73c\ub85c \uc8fc\uac00 \uc0c1\uc2b9 \uc911\uc774\uc5c8\uace0, \ubbf8\uad6d \uc790\ub3d9\ucc28 \ud68c\uc0ac\uac00 \uc6d0\uc790\uc7ac\ub97c \uc81c\uacf5\ud558\ub294 \ub300\uac00\ub85c \uc790\ub3d9\ucc28\ub97c \uc2f8\uac8c \uacf5\uae09\ubc1b\ub294 \uacc4\uc57d \uc598\uae30\uac00 \ub098\uc624\uace0 \uc788\uc5c8\ub2e4. \uc800\uc790\ub294 \uc774\ub7f0 \uc2dd\uc73c\ub85c \uc774\ud0c8\ub9ac\uc544 \uc0b0\uc5c5\uc774 \ubd80\ud65c\ud560 \uac83\uc774\ub77c \ud655\uc2e0\ud558\uace0, \uac00\uc7a5 \ucd5c\uc545\uc774\ub77c \uc18c\ubb38\uc774 \ub3cc\ub358 \uc790\ub3d9\ucc28 \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc744 \ub9e4\uc218\ud588\ub2e4. \uba87 \ub2ec \ub4a4 \uc8fc\uac00\ub294 3\ubc30 \uc0c1\uc2b9\ud588\ub2e4. \ube0c\ub85c\ucee4\uac00 \ud314\ub77c\uace0 \ud588\uc73c\ub098 \uc624\ud788\ub824 \ucd94\uac00 \ub9e4\uc218\ud588\ub2e4. **\uc8fc\uac00\ub294 \uacb0\uad6d 10\ubc30 \uc774\uc0c1 \uae09\ub4f1\ud588\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 26\n\n**\uc778\ub0b4**\n\n> \uc8fc\uc2dd\uc740 \uba38\ub9ac\ub85c \ubcf4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc5c9\ub369\uc774\ub85c \ubcf8\ub2e4.\n\n\ud22c\uc790\ud574\uc11c \uc5bb\uc740 \ub3c8\uc740 \uace0\ud1b5\uc758 \ub300\uac00\ub85c \ubc1b\ub294 \ub3c8\uc774\ub2e4. \uc8fc\uc2dd\ud22c\uc790\uc5d0\uc11c \uace0\ud1b5\uc2a4\ub7fd\uc9c0 \uc54a\uac8c \ub3c8\uc744 \ubc8c\uace0 \uc788\ub2e4\uba74, \ub0b4\uac00 \uc9c4\uc815\uc73c\ub85c \ub3c8\uc744 \ubc8c\uace0 \uc788\ub294\uac00\ub97c \uc0dd\uac01\ud574 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \ub178 \ud398\uc778 \ub178 \uac8c\uc778(No pain, no gain). **\ud22c\uc790\ub77c\ub294 \uac74\ubb3c\uc758 \uae30\ucd08\uac00 \ud2bc\ud2bc\ud558\uace0 \uc62c\ubc14\ub974\uba74 \ubaa8\ub4e0 \uac83\uc740 \uc2dc\uac04\uc758 \ubb38\uc81c\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 27\n\n**\ud589\uc6b4\uc774 \ub530\ub77c\uc57c \ud070\ub3c8\uc744 \ubc8c \uc218 \uc788\ub2e4.** \uc704\uc758 \uc138 \uac00\uc9c0(\ub3c8, \uc0dd\uac01, \uc778\ub0b4)\uc640 \ud589\uc6b4\uc774 \uacb0\ud569\ub41c\ub2e4\uba74 \ud070 \ubd80\ub97c \uc774\ub8f0 \uc218 \uc788\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 28\n\n**\ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 \ub2ec\uac40**\n\n\ub2ec\uac40\uc740 \uc138 \uac1c\uc758 \uad6d\uba74\uc73c\ub85c \ub098\ub25c\ub2e4. A \uad6d\uba74(\ub9e4\uc218), B \uad6d\uba74(\uad00\ub9dd), C \uad6d\uba74(\ub9e4\ub3c4):\n\n**A \uad6d\uba74 \u2014 \ub9e4\uc218**\n\n- **A1: \uc870\uc815 \uad6d\uba74** \u2014 \uac70\ub798\ub7c9\uc740 \uc801\uace0 \uc8fc\uc2dd \uc18c\uc720\uc790\ub294 \uc801\ub2e4. \uc8fc\uc2dd\uc5d0 \ub300\ud55c \ub274\uc2a4\uac00 \uc5c6\ub2e4. \uae08\u00b7\ubd80\ub3d9\uc0b0 \ub4f1\uc5d0\ub9cc \uad00\uc2ec\uc774 \uc788\uc73c\uba70 \ub450\ub824\uc6c0\uacfc \ub9e4\uc218\ub7c9\uc774 \uac19\ub2e4. \uc18c\uc2e0\ud30c\uac00 \uc911\uc6a9\ud558\uc5ec \ub9e4\uc218\ud55c\ub2e4.\n- **A2: \ub3d9\ud589 \uad6d\uba74** \u2014 \uac70\ub798\ub7c9\uacfc \uc8fc\uc2dd \uc18c\uc720\uc790\uac00 \uc99d\uac00\ud55c\ub2e4. \uc8fc\uac00\ub294 \uc870\uae08\uc529 \uc0c1\uc2b9\ud55c\ub2e4. \uc0c1\ud669\uc774 \uc88b\uc73c\uba74 \uc0c1\uc2b9, \uc0c1\ud669\uc774 \uc548 \uc88b\uc73c\uba74 \ud558\ub77d. \uc18c\uc2e0\ud30c\uac00 \uc5ec\uc804\ud788 \ub9e4\uc218\ud55c\ub2e4.\n- **A3: \uacfc\uc7a5 \uad6d\uba74** \u2014 \uac70\ub798\ub7c9\uacfc \uc8fc\uc2dd \uc18c\uc720\uc790\uac00 \ud3ed\uc99d\ud55c\ub2e4. \ubd80\ud654\ub1cc\ub3d9\ud30c\uac00 \ucc38\uc5ec\ud55c\ub2e4. \ud765\ubd84\ub41c \ubd84\uc704\uae30\ub97c \ud0c0\uace0 \uc8fc\uac00\uac00 \ub300\uaddc\ubaa8 \uc0c1\uc2b9\ud55c\ub2e4. \uc77c\ubc18 \ub300\uc911\uc774 \ub300\uac70 \uc720\uc785\ub41c\ub2e4. \uc5b8\ub860\uc774 \ub300\uaddc\ubaa8 \uc8fc\uc2dd \ub9e4\uc785\uc744 \uc5f0\uc77c \ubcf4\ub3c4\ud55c\ub2e4. \uc0ac\uad50 \ubaa8\uc784\uc5d0\uc11c \uc8fc\uc2dd \uc774\uc57c\uae30\uac00 \uc8fc \ud654\ub450\uac00 \ub41c\ub2e4. \ub3c8\uc744 \ubc8c\uc5c8\ub2e4\uace0 \uc790\ub791\ud558\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc544\uc9c4\ub2e4. \uace0\ud3c9\uac00\ub41c \uc885\ubaa9\uc744 \uae30\uaebc\uc774 \uc0ac\uba70, \uc800\ud3c9\uac00 \uc885\ubaa9\uc740 \uac70\ub4e4\ub5a0\ubcf4\uc9c0\ub3c4 \uc54a\ub294\ub2e4. **\uc18c\uc2e0\ud30c\ub294 \uc774\ub54c \uc870\uc6a9\ud788 \ub9e4\ub3c4\ud55c\ub2e4.** A3 \uad6d\uba74\uc5d0\uc11c \ucd5c\uace0\uc810\uc73c\ub85c \ub118\uc5b4\uac00\ub294 \uc0ac\uc774\uc5d0 \uc5ec\ub7ec \ucc28\ub840 \uae08\ub9ac \uc778\uc0c1\uc774 \ub2e8\ud589\ub41c\ub2e4.\n\n**B \uad6d\uba74 \u2014 \uad00\ub9dd**\n\n- **B1: \uc870\uc815 \uad6d\uba74** \u2014 \uac70\ub798\ub7c9\uacfc \uc8fc\uc2dd \uc18c\uc720\uc790\ub294 \uc11c\uc11c\ud788 \uac10\uc18c\ud55c\ub2e4. \uc57d\uac04\uc758 \ub9e4\ub3c4\uc5d0\ub3c4 \uc8fc\uac00\ub294 \uc989\uc2dc \ud558\ub77d\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \ub9e4\uc218\uc790\uac00 \uc5c6\uace0 \ud22c\uc790\uc790\ub4e4\uc740 \uc608\ubbfc\ud574\uc9c0\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc18c\uc2e0\ud30c\ub4e4\uc740 \ub9e4\ub3c4\ub97c \ub05d\ub9c8\uce58\uace0 \ud604\uae08\uc744 \ubcf4\uc720\ud55c\ub2e4.\n- **B2: \ub3d9\ud589 \uad6d\uba74** \u2014 \uac70\ub798\ub7c9\uc740 \uc99d\uac00\ud558\uace0 \uc8fc\uc2dd \uc18c\uc720\uc790\ub294 \uacc4\uc18d \uac10\uc18c\ud55c\ub2e4. \uc2dc\uc7a5\uc758 \ubd84\uc704\uae30\uac00 \uadf9\ub3c4\ub85c \uc608\ubbfc\ud574\uc9c4\ub2e4. \uc18c\uc2e0\ud30c\ub294 \ud604\uae08\uc744 \ubcf4\uc720\ud558\uace0 \uc788\uc73c\ub2c8 \ud3b8\uc548\ud558\ub2e4. \ub610\ub294 \uc870\uae08\uc529 \ub9e4\uc218\ub97c \uc2dc\uc791\ud55c\ub2e4.\n- **B3: \uacfc\uc7a5 \uad6d\uba74** \u2014 \uac70\ub798\ub7c9\uc774 \ud3ed\uc8fc\ud558\uace0 \uc8fc\uc2dd \uc18c\uc720\uc790\ub294 \ucd5c\uc800\ub97c \ucc0d\ub294\ub2e4. \ube44\uad00\uc8fc\uc758\uac00 \ud33d\ubc30\ud558\uace0 \uc8fc\uac00\ub294 \ud3ed\ub77d\ud55c\ub2e4. \uae30\uc5c5\uc740 \uba40\uca61\ud574\ub3c4 \ub2e4\ub4e4 \ub9e4\ub3c4\ud558\uae30 \ubc14\uc058\ub2e4. **\uc18c\uc2e0\ud30c\uac00 \uc870\uc6a9\ud788 \ud5d0\uac12\uc5d0 \ub9e4\uc218\ud558\uae30 \uc2dc\uc791\ud55c\ub2e4.** B3 \uad6d\uba74\uc5d0\uc11c \ucd5c\uc800\uc810\uc744 \ub118\uc5b4\uac00\ub294 \uc2e0\ud638\uac00 \ubc14\ub85c \uc720\ub3d9\uc131 \uc99d\uac00 \uacc4\ud68d \ubc1c\ud45c\ub2e4 \u2014 \uc989 \uae08\ub9ac \uc778\ud558\uc774\ub2e4.\n\n> **\ub098\ub294 \uc815\uc2e0\uc801\u00b7\uac10\uc131\uc801\u00b7\ubb3c\uc9c8\uc801\uc73c\ub85c \uc900\ube44\ub418\uc5b4 \uc788\ub2e4. \uc989 \ub098\ub294 \ud604\uae08\uc744 \ubcf4\uc720\ud558\uace0 \uc788\uc5c8\ub2e4.** 1987\ub144 \uc8fc\uc2dd\uc2dc\uc7a5 \uacf5\ud669 \uc774\ud6c4, \uc5f0\uc900 \uc758\uc7a5 \uc568\ub7f0 \uadf8\ub9b0\uc2a4\ud380\uc740 \uc774\ub807\uac8c \uc774\uc57c\uae30\ud588\ub2e4: \"\uc5b4\ub824\uc6c0\uc5d0 \ucc98\ud55c \uae30\uc5c5\uc758 \uc9c0\uc6d0\uc744 \uc704\ud574 \uc790\uae08 \uc720\ub3d9\uc131\uc744 \ub298\ub9b4 \uacc4\ud68d\uc785\ub2c8\ub2e4.\" \ub098\ub294 \uadf8 \ub9d0\ub85c \uc704\uae30\uac00 \ub05d\ub0ac\ub2e4\uace0 \uc0dd\uac01\ud588\ub2e4. \uadf8\ub9b0\uc2a4\ud380\uc758 \ubc1c\uc5b8\uc740 \uc18c\uc2e0\ud30c \ud22c\uc790\uc790\ub4e4\uc5d0\uac8c \uc99d\uc2dc \uc9c4\uc785\uc744 \uc54c\ub9ac\ub294 \uc885\uc18c\ub9ac\ub85c \ub4e4\ub838\ub2e4. \ud638\ud669\uc740 \uc2dc\uac04 \ubb38\uc81c\uc600\ub2e4. \ud558\uc9c0\ub9cc \uacbd\uc81c\ud559\uc790\ub4e4\uc740 \uc2ec\uac01\ud55c \uacbd\uc81c\uc704\uae30\ub97c \uc608\uace0\ud558\uc600\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 29\n\n**\ubd90\uacfc \ud3ed\ub77d\uc740 \ubd84\ub9ac\ud560 \uc218 \uc5c6\ub294 \uc30d\ub465\uc774\uc774\uba70, \uc8fc\uac00\ub294 \ubc18\ub4dc\uc2dc \ud3ed\ub77d\ud55c\ub2e4. \uc774\uac83\uc740 \uc601\uc6d0\ubd88\ubcc0\uc758 \ubc95\uce59\uc774\ub2e4.** \ubd90 \uc5c6\ub294 \ud3ed\ub77d \uc5c6\uace0, \ud3ed\ub77d \uc5c6\uc774\ub3c4 \ubd90 \uc5c6\ub2e4. 400\uc5ec \ub144\uc5d0 \uc774\ub974\ub294 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uc5ed\uc0ac\ub294 \ubd90\uacfc \ud3ed\ub77d\uc758 \ubc18\ubcf5\uc774\uc5c8\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 30\n\n\ubb34\uac00\uce58\ud55c \uac83\uc774 \uc778\ud50c\ub808\uc774\uc158\ub418\uc5b4 \ube44\uc2f8\uc84c\ub2e4\uba74 \u2014 **\ud56d\uc0c1** \ud3ed\ub77d\uc774 \uc874\uc7ac\ud588\ub2e4. \uac00\uaca9\uc758 \uc0c1\uc2b9\uc740 \ubb34\ucc45\uc784\ud55c \uc120\uc804\uc758 \ub355\ud0dd\uc774\ub2e4. \uadf8 \uc120\uc804\uc740 \uc99d\uad8c\uc778, \ube0c\ub85c\ucee4, \ud380\ub4dc \ub9e4\ub2c8\uc800 \ub4f1\uc774 \ud574\uc654\ub2e4. \uc18c\uc561 \ud22c\uc790\uc790\uc758 \uadc0\uc5d0 \uacbd\uace0\ub294 \ub4e4\ub9ac\uc9c0 \uc54a\uc558\uc73c\uba70, \uadf8\ub4e4\uc740 \uadf8\uc800 \ud750\ub984\uc5d0 \ud569\ub958\ud558\ub294 \ub370 \ubab0\ub450\ud558\ub2e4\uac00 \uacb0\uad6d \ud53c\ud574\ub97c \uc785\uc5c8\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 31\n\n**\ud504\ub791\uc2a4 \uc8fc\uc2dd\uc2dc\uc7a5\uc744 \ud30c\uba78\ub85c \uc774\ub048 \uc5ed\uc0ac\uc801 \uc0ac\ub840 \u2014 \uc874 \ub85c(John Law)**\n\n\uc644\ubcbd\ud55c \uc120\uc804 \ub355\ud0dd\uc5d0 \uc8fc\uc2dd\uc2dc\uc7a5\uc774 \uc644\uc804\ud788 \uace0\ud3c9\uac00\ub418\uc5c8\uace0, \uc870\uae08\ub9cc \ub0c9\uc815\ud558\uac8c \uc0b4\ud3b4\ubd10\ub3c4 \ud130\ubb34\ub2c8\uc5c6\ub294 \uac00\uaca9\uc5d0 \uac70\ub798\ub418\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\uc5c8\uc74c\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \uc0ac\ub78c\ub4e4\uc740 \ubbf8\uccd0\uc11c \uacc4\uc18d \uc8fc\uc2dd\uc744 \ub9e4\uc785\ud588\ub2e4. \uacb0\uad6d \uc644\uc804 \ud3ed\ub77d\uacfc 50\ub144\uac04\uc758 \uc554\ud751\uae30\uac00 \ucc3e\uc544\uc654\ub2e4.\n\n18\uc138\uae30 \ud504\ub791\uc2a4\ub294 \uc8fc\uac00 \ub300\ud3ed\ub77d\uc744 \uacbd\ud5d8\ud588\ub2e4. \ucc9c\uc7ac\uc801 \ub2a5\ub825\uc758 \uc874 \ub85c\ub294 \ud504\ub791\uc2a4\ub97c \uad6c\ud560 \uc778\ubb3c\ub85c \ucd94\uc559\ubc1b\uc558\uace0, \ucd5c\ucd08\uc758 \uc911\uc559\uc740\ud589\uc744 \uc124\ub9bd\ud588\ub2e4. \uadc0\uc871\ub4e4\uc774 \uc8fc\uac00\ub97c \uacc4\uc18d \uc62c\ub9ac\ub77c\uace0 \uc555\ub825\uc744 \ub123\uc5c8\uace0, \ub300\ub300\uc801\uc73c\ub85c \uc8fc\uc2dd\uc744 \ud64d\ubcf4\ud558\uae30 \uc2dc\uc791\ud588\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc88b\uc740 \ub73b\uc73c\ub85c \ud588\ub2e4\uace0 \ud55c\ub2e4. \uc644\ubcbd\ud55c \uc120\uc804 \ub355\ud0dd\uc5d0 \uc0c8\ub85c\uc6b4 \uc8fc\uc2dd \ubc14\ub78c\uc774 \ubd88\uace0 \uc790\ubcf8\uc774 \ud758\ub7ec\ub4e4\uc5b4 \uc654\ub2e4. \uc0c8\ub85c\uc6b4 \uc8fc\uc2dd\uc744 \ub9e4\uc218\ud558\uae30 \uc704\ud574 \uc99d\uad8c\uac70\ub798\uc18c \uc55e\uc5d0 \uc904\uc744 \uc130\uace0, \ud130\ubb34\ub2c8\uc5c6\ub294 \uac00\uaca9\uc5d0 \ub9e4\uc218\uac00 \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\uc5c8\ub2e4. \uadf8\uac83\uc744 \uacc4\uc0b0\ud55c \uc18c\uc2e0\ud30c \ud22c\uc790\uc790\ub4e4\uc774 \uc870\uc6a9\ud788 \ube60\uc838\ub098\uc654\ub2e4. \uc810\ucc28 \uc8fc\uac00\ub294 \ud558\ub77d\ud558\ub2e4\uac00 \uacb0\uad6d \ud3ed\ub77d\ud588\ub2e4. \uba87 \uc8fc \uc804\uae4c\uc9c0\ub9cc \ud574\ub3c4 \ubd80\uc790\uc600\ub358 \uc0ac\ub78c\ub4e4\uc774 \uac00\ub09c\ud574\uc84c\uace0, \ud558\ub8fb\ubc24 \uc0ac\uc774\uc5d0 \uac70\uc9c0\uac00 \uc18d\ucd9c\ud588\ub2e4. **\uadf8 \uc774\ud6c4 \ud504\ub791\uc2a4 \uc8fc\uc2dd\uc2dc\uc7a5\uc740 \uc57d 50\ub144\uac04 \uc554\ud751\uae30\ub97c \ubcf4\ub0c8\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 32\n\n**\uc131\uacf5 \uc804\ub7b5\uc740 \ub0a8\ub4e4\uacfc \ubc18\ub300\ub85c \ud558\ub294 \uac83.** \ud22c\uc790\uc790\ub4e4\uc740 \uc18c\uc2e0\ud30c\uc5d0 \uc18d\ud574\uc57c \ud558\uba70 \ub0a8\ub4e4\uacfc \ubc18\ub300\ub85c \ud589\ub3d9\ud574\uc57c \ud55c\ub2e4.\n\n- A1 \uad6d\uba74\uc5d0\uc11c \ub9e4\uc218\ud574\uc57c \ud558\uba70, \ub9e4\uc218 \ud6c4\uc5d0 \ub354 \ub5a8\uc5b4\uc838\ub3c4 \ub3d9\uc694\ud558\uc9c0 \ub9d0\uc544\uc57c \ud55c\ub2e4.\n- B \uad6d\uba74\uc5d0\uc11c\ub294 \uad00\ub9dd\uc790\ub85c \uadf8 \uc0c1\ud669\uc5d0 \ubab8\uc744 \ub9e1\uae30\uba74 \ub41c\ub2e4.\n- C \uad6d\uba74(A3)\uc5d0\uc11c\ub294 \uc2ac\uc2ac \uc2dc\uc7a5\uc5d0\uc11c \ub098\uac08 \uc900\ube44\ub97c \ud574\uc57c \ud55c\ub2e4.\n\n> **\uc8fc\uc2dd\uc2dc\uc7a5\uc744 \ubcf4\ub294 \uae30\uc220\uc758 \ud575\uc2ec\uc740 \ud604\uc7ac \uc2dc\uc7a5\uc774 \uc5b4\ub514\uc5d0 \uc704\uce58\ud558\uace0 \uc788\ub294\uc9c0 \uc815\ud655\ud788 \uc544\ub294 \ub370 \uc788\ub2e4.**\n\n\ub0c9\uc815\ud558\uace0 \uac1d\uad00\uc801\uc73c\ub85c \ubcf8\ub2e4\uba74 \ub2ec\uac40 \ubaa8\ud615\uc744 \ud1b5\ud574 \ud604\uc7ac \uc2dc\uc7a5\uc758 \uc704\uce58\ub97c \ub204\uad6c\ub77c\ub3c4 \uc27d\uac8c \ud310\ub2e8\ud560 \uc218 \uc788\uc744 \uac83\uc774\ub2e4.\n\n**\uc2dc\uc7a5\uc758 \uc704\uce58\ub97c \ud30c\uc545\ud558\ub294 \ub450 \uac00\uc9c0 \uc2e0\ud638:**\n\n- \uc2dc\uc7a5\uc5d0 \uc545\uc7ac\uc5d0\ub3c4 \ub354 \uc774\uc0c1 \ud558\ub77d\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74, \uadf8\uac83\uc740 \uc2dc\uc7a5\uc774 \uacfc\uc789 \ub9e4\ub3c4 \uc0c1\ud0dc\ub77c\ub294 \uc774\uc57c\uae30\ub2e4. \uc989 \ub300\ubd80\ubd84\uc758 \uc8fc\uc2dd\uc744 \uc18c\uc2e0\ud30c\uac00 \ubcf4\uc720\ud558\uace0 \uc788\ub2e4\uace0 \ubd10\uc57c \ud55c\ub2e4.\n- \ubc18\ub300\ub85c \uc2dc\uc7a5\uc5d0 \ud638\uc7ac\uc5d0\ub3c4 \ub354 \uc774\uc0c1 \uc0c1\uc2b9\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74, \uadf8\uac83\uc740 \uc2dc\uc7a5\uc774 \uacfc\uc789 \ub9e4\uc218 \uc0c1\ud0dc\ub77c\ub294 \uc774\uc57c\uae30\ub2e4. \uc989 \ub300\ubd80\ubd84\uc758 \uc8fc\uc2dd\uc744 \ubd80\ud654\ub1cc\ub3d9\ud30c\uac00 \ubcf4\uc720\ud558\uace0 \uc788\ub2e4\uace0 \ubd10\uc57c \ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 33\n\n**\uac70\ub798\ub7c9\uc740 \ub9ce\uc740 \uac83\uc744 \uc554\uc2dc\ud55c\ub2e4 \u2014 \uac70\uc758 \uc554\uae30 \uc218\uc900\uc73c\ub85c \uc678\uc6cc\uc57c \ud55c\ub2e4.**\n\n| \uac70\ub798\ub7c9 | \uc8fc\uac00 \ubc29\ud5a5 | \uc758\ubbf8 |\n|---|---|---|\n| \uc99d\uac00 | \ud558\ub77d | \ubd80\ud654\ub1cc\ub3d9\ud30c\uc5d0\uc11c \uc18c\uc2e0\ud30c\ub85c \uc8fc\uc2dd\uc774 \ub118\uc5b4\uac00\uace0 \uc788\ub2e4. \uac15\ub825\ud55c \uc0c1\uc2b9 \uc6b4\ub3d9\uc758 \uc804\uc870. |\n| \uac10\uc18c | \ud558\ub77d | \uc88b\uc9c0 \uc54a\uc740 \uc2e0\ud638. |\n| \ub9e4\uc6b0 \ub9ce\uc74c | \uc0c1\uc2b9 | \ub354 \uc88b\uc9c0 \uc54a\uc740 \uc2e0\ud638. (\uc77c\ubc18\uc801\uc73c\ub85c \uc88b\ub2e4\uace0 \uc5ec\uaca8\uc9c0\uc9c0\ub9cc \uadf8\ub807\uc9c0 \uc54a\ub2e4.) |\n| \uc801\uc74c | \uc11c\uc11c\ud788 \uc0c1\uc2b9 | \uc544\uc8fc \uae0d\uc815\uc801 \uc2e0\ud638. \uc774\ub54c \uc2dc\uc7a5 \ubd84\uc704\uae30\uac00 \uc88b\uc9c0 \uc54a\ub2e4\uba74 \ub354\ud560 \ub098\uc704 \uc5c6\ub2e4. |\n| \ub9ce\uc9c0 \uc54a\uc74c | \uc0c1\uc2b9 \ub610\ub294 \ud558\ub77d | \ub3d9\uc77c\ud55c \ud750\ub984\uc774 \uc9c0\uc18d\ub41c\ub2e4\ub294 \uc2e0\ud638. |\n| \uae09\uc99d | \uae09\ub4f1 | \uc704\ud5d8 \uc2e0\ud638. |\n\n\uc608\uc804\uc774\ub098 \uc9c0\uae08\uc774\ub098 \uc774\ud6c4\ub098, \uc774 \uacf5\uc2dd\ub4e4\uc740 \uc544\ub9c8 \ub4e4\uc5b4\ub9de\uc744 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 34\n\n**\uac00\uc7a5 \ubd84\uba85\ud55c \uc554\uc2dc\ub294 \uc77c\ubc18\uc801\uc778 \uc5ec\ub860\uc774 \uc5b4\ub5a0\ud55c\uac00\ub97c \ubcf4\uba74 \uc54c \uc218 \uc788\ub2e4.**\n\n\uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \ub300\ud55c \uc5b8\ub860 \ubcf4\ub3c4\uac00 \uae0d\uc815\uc801\uc774\uba74, \uc774\uc804\uc5d0 \uad00\uc2ec \uc5c6\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc8fc\uc2dd\uc5d0 \uad00\uc2ec\uc744 \uac00\uc9c0\uac8c \ub418\uba70 \uc774\ub294 A3 \uad6d\uba74\uc774\ub77c\ub294 \uac15\ub825\ud55c \uc2e0\ud638\uc774\ub2e4. **\ub9c8\uc9c0\ub9c9 \ube44\uad00\uc8fc\uc758\uc790\uae4c\uc9c0 \uc57d\uac04 \uae0d\uc815\uc801\uc774 \ub41c\ub2e4\uba74, \uc774\uac83\uc740 A3 \uad6d\uba74\uc758 \ub05d\uc790\ub77d\uc774\ub77c\uace0 \ubcfc \uc218 \uc788\ub2e4.**\n\n> \"\uc8fc\uc2dd\uc758 \uc8fc\uc790\ub3c4 \ubab0\ub790\ub358 \uc6b0\ub9ac \uc544\ub0b4\uac00 \uacf5\ubaa8\uc8fc\uc5d0 \uc5f4\ubcc0\uc744 \ud1a0\ud558\uace0, \uc8fc\uc2dd\ud558\uba74 \ud328\uac00\ub9dd\uc2e0\ud55c\ub2e4\ub358 \uc800\ud76c \uc5b4\uba38\ub2c8\uac00 \uc0bc\uc131\uc804\uc790\ub97c \uc0b4\uae4c \ub9d0\uae4c \uace0\ubbfc\ud55c\ub2e4.\"\n\n\uae0d\uc815\uc801 \ud604\uc0c1\ub4e4\uc774 \uc9d1\uc911\ub418\uba74 \uc8fc\uac00\ub294 \ud604\uc2e4\uacfc\uc758 \uc5f0\uad00\uc131\uc744 \uc0c1\uc2e4\ud558\uac8c \ub41c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 35\n\n**\ub69c\ub837\ud55c \uc8fc\uad00\uc758 \uc18c\uc720 \uc5ec\ubd80\uac00 \uc131\uacf5\uc758 \uc870\uac74\uc774\ub2e4.**\n\n\uc5ec\ub860\uc5d0 \ubc18\ud558\uc5ec \ub9e4\ub9e4\ud558\ub294 \uac83\uc740 \ucc38\uc73c\ub85c \uc5b4\ub835\ub2e4. \uc790\uc2e0\uc758 \uc8fc\uad00\uc744 \ud3ec\uae30\ud558\uba74\uc11c \ub300\uc911\uc5d0 \ud729\uc4f8\ub9b4 \ub54c \ud558\ub294 \uc0dd\uac01\uc740 \ubc14\ub85c \uc774\ub807\ub2e4: \"\uc774\ub860\uc801\uc73c\ub85c\ub294 \uc774\ub807\uac8c \ud574\uc57c\uc9c0\ub9cc, \uc774\ubc88\uc740 \uc0c1\ud669\uc774 \ub2ec\ub77c.\" **\ub300\uc911\uc758 \ud788\uc2a4\ud14c\ub9ac\uc5d0 \ud30c\ubb3b\ud788\uc9c0 \uc54a\uc73c\ub824\uba74 \ud6c8\ub828\uc744 \ud574\uc57c \ud55c\ub2e4. \ub0c9\uc815\ud558\ub2e4 \ubabb\ud574 \ub0c9\uc18c\uc801\uc774\uc5b4\uc57c \ud55c\ub2e4.**\n\n\ub9cc\uc57d A1 \uad6d\uba74\uc774\ub098 A2 \uad6d\uba74\uc5d0\uc11c \ud558\ub77d\uc774 \ub098\uc640\ub3c4 \uadf8\uac83\uc744 \ubc18\ub4dc\uc2dc \ucc38\uc544\uc57c \ud55c\ub2e4. \ud558\uc9c0\ub9cc \uc804\uc7c1\uc774\ub098 \uc911\uc694\ud55c \uc815\uce58\u00b7\uacbd\uc81c\u00b7\uae08\uc735\uc815\ucc45\u00b7\uc815\uad8c \uad50\uccb4 \ub4f1 \ud5e4\uc544\ub9ac\uc9c0 \ubabb\ud55c \uc911\uc694\ud55c \ubcc0\uc218\uac00 \ubc1c\uc0dd\ud558\uc600\uc744 \ub54c\ub294 \uc2e0\uc18d\ud788 \uacb0\uc815\uc744 \ub0b4\ub824 \uadf8\uacf3\uc5d0\uc11c \ub2f9\uc7a5 \ub6f0\uc5b4\ub0b4\ub824\uc57c \ud55c\ub2e4. **\ub9cc\uc57d \ubc84\ud2f0\ub824\uba74 \ub05d\uae4c\uc9c0 \ubc84\ud168\ub77c.**\n\n---\n\n## \ud3ec\uc778\ud2b8 36\n\n**A3 \uad6d\uba74\uc744 \uc990\uae30\ub418, \ud604\uae08 \ud750\ub984\uc774 \uac11\uc790\uae30 \ub9c9\ud788\uba74 \uc544\ubb34\ub9ac \uc0c1\ud669\uc774 \uc88b\uac8c \ubcf4\uc774\ub354\ub77c\ub3c4 \uacfc\uac10\ud558\uac8c \uc2dc\uc7a5\uc744 \ube60\uc838\ub098\uc640\uc57c \ud55c\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 37\n\n\ub098\ub294 \uacf5\ub9e4\ub3c4\ub97c \ud558\uc5ec \ud070\ub3c8\uc744 \ubc8c\uc5c8\ub2e4. \ubd84\uba85\ud788 A3 \uad6d\uba74\uc774\ub77c \ud310\ub2e8\ud588\uace0 \uc8fc\uac00\uc758 \ud558\ub77d\uc740 \ubd88 \ubcf4\ub4ef \ubed4\ud588\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ub17c\ub9ac\uc801\uc73c\ub85c \ud3ed\ub77d\uc744 \uc608\uacac\ud558\uc600\uace0, \uadf8\uac83\uc740 \uc801\uc911\ud588\ub2e4. \uacbd\ud5d8\uc774 \uc313\uc774\uace0 \ub098\ub2c8 \uc778\uc704\uc801\uc73c\ub85c \uc870\uc131\ub41c \ubd90\uc5d0\uc11c \uc815\ud655\ud55c \uc9c4\ub2e8\uc744 \ub0b4\ub9b4 \uc218 \uc5c6\uc5c8\uc9c0\ub9cc, **\ubcf8\ub2a5\uc801\uc73c\ub85c \uc704\ud5d8\uc744 \uac10\uc9c0\ud588\ub2e4.** \ucd08\ubcf4\uc790\ub77c\uba74 \ubb34\uc870\uac74 \uac15\uc138\uc7a5\uc5d0\uc11c \ud22c\uc790\ub97c \uc2dc\uc791\ud558\uae38 \uad8c\uc7a5\ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 38\n\n**\uc815\ubcf4 \u2014 \uc18c\uc790\uc758 \ub3c4\uad6c**\n\n\ub098\ub294 \uc815\ubcf4\ub97c \ucc3e\uc544 \ud5e4\ub9e4\uc9c0 \uc54a\ub294\ub2e4. \uadf8\uc800 \ubc1c\uacac\ud560 \ubfd0\uc774\ub2e4. \uc77c\uc0c1 \uc0dd\ud65c \uc5b4\ub514\uc11c\ub4e0 \uc815\ubcf4\ub97c \uc5bb\ub294\ub2e4. \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ubaa8\ub4e0 \uac83\uc774 \uc815\ubcf4\ub2e4. \ub9cc\ub098\ub294 \ud3c9\ubc94\ud55c \uc0ac\ub78c\uc5d0\uac8c \ubb3c\uc74c\uc73c\ub85c\uc368 \uc815\ubcf4\ub97c \uc5bb\ub294\ub2e4.\n\n**\uc2e0\ubb38\u00b7\ub274\uc2a4 \ub4f1\uc5d0\uc11c \ub098\uc624\ub294 \uae30\uc0ac\uc5d0\ub294 \uc911\uc694\ud55c \uc815\ubcf4\uac00 \uc5c6\ub2e4.** \uadf8\uac83\uc740 \uc774\ubbf8 \ub204\uad6c\ub098 \uc54c\uc544\ubc84\ub9b0 \uc0ac\uc2e4\uc774\ub2e4. **\uc911\uc694\ud55c \uac83\uc740 \uc2e0\ubb38\uacfc \ub274\uc2a4\uc758 \ud589\uac04\uc744 \uc77d\uc744 \uc904 \uc54c\uc544\uc57c \ud55c\ub2e4\ub294 \uac83\uc774\ub2e4.** \uac00\uc7a5 \ud765\ubbf8 \uc5c6\ub294 \uac83\uc774 \uc2dc\uc138 \ubcc0\ub3d9\uc5d0 \ub300\ud55c \uc5b8\ub860 \ubcf4\ub3c4\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 39\n\n**\uacf5\uc2dc\u00b7\uc2e4\uc801 \ubc1c\ud45c\ub97c \ubcf4\uace0 \ud22c\uc790\ud558\uc9c0 \ub9c8\ub77c \u2014 '\ud329\ud2b8 \ud480 \ud544\ub4dc(Fact fulfilled)' \ud604\uc0c1**\n\n\uc5b4\ub5a4 \uae30\uc5c5\uc758 2\ubd84\uae30 \uc2e4\uc801\uc774 \uc88b\uc744 \uac83\uc774\ub77c\ub294 \uc815\ubcf4\uac00 \uc720\ud3ec\ub418\uba74\uc11c \uae30\ub300\uac10\uc774 \uc62c\ub77c\uac00\uace0 \uc8fc\uac00\ub294 \uc0c1\uc2b9\ud55c\ub2e4. \uacf5\uc2dc\uac00 \ub418\uae30 \uc804\uc5d0 \uc0ac\ub78c\ub4e4\uc740 \uc8fc\uc2dd\uc744 \uc0ac\ub4e4\uc778\ub2e4. \uc774\ubbf8 \uc120\ubc18\uc601\uc774 \ub418\uace0 \uc788\ub294 \uac83\uc774\ub2e4. \uc2e4\uc801\uc774 \ubc1c\ud45c\ub418\uace0 \uae30\ub300\uce58\uc5d0 \ubd80\ud569\ud558\uac8c \ub418\uba74 \uadf8\ub54c\ubd80\ud130 \uc8fc\uac00\ub294 \ud558\ub77d\ud55c\ub2e4. **\uc65c\uc77c\uae4c? \uc774\ubbf8 \uc608\uacac\ud588\ub358 \uc77c\uc774 \uc77c\uc5b4\ub0ac\uace0, \ubaa8\ub450\uac00 \uacf5\uc2dc \uc774\uc804\uc5d0 \uc8fc\uc2dd\uc744 \ub9e4\uc218\ud588\uc73c\ubbc0\ub85c \ub354 \uc774\uc0c1 \ub9e4\uc218\uc790\uac00 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4.**\n\n\ubc18\ub300 \uc0c1\ud669\ub3c4 \ub9c8\ucc2c\uac00\uc9c0\ub2e4. \uc804\ubb38\uac00\uac00 \uc5b4\ub5a4 \uacb0\uc190 \uc218\uce58\ub97c \uc608\uc0c1\ud588\ub2e4\uba74 \uc8fc\uc2dd\uc740 \ubbf8\ub9ac \ud314\ub9b0\ub2e4. \uacf5\uc2dc \uc804\uc5d0 \ucd5c\uc800\uc810\uc744 \ucc0d\uace0, \ub354 \uc774\uc0c1\uc758 \ub9e4\ub3c4\uc790\uac00 \uc5c6\uc73c\ubbc0\ub85c \uc870\uae08\uc758 \ub9e4\uc218\uc138\uc5d0 \uc8fc\uac00\ub294 \uc0c1\uc2b9\ud55c\ub2e4. **\uacb0\uad6d \uc774 \ud604\uc0c1\ub3c4 \uacf5\uae09\uacfc \uc218\uc694\ub85c \uc124\uba85\uc774 \uac00\ub2a5\ud558\ub2e4.**\n\n> **\uc774\ubbf8 \uc54c\ub824\uc9c4 \uc0ac\uc2e4\ub85c \uc811\uadfc\ud574\uc11c\ub294 \uc808\ub300 \uc548 \ub41c\ub2e4.** \uc0c1\uc0c1\ub825\uacfc \uc0dd\uac01\uc73c\ub85c \uc811\uadfc\ud574\uc57c\uc9c0, \uc774\ubbf8 \uc54c\ub9b0 \uc0ac\uc2e4\ub85c \uc811\uadfc\ud588\ub2e4\uac00\ub294 \uc120\ubc18\uc601\ub41c \uace0\uc810\uc5d0\uc11c \ub2f9\ud560 \uc218 \uc788\ub2e4.\n\n\uc804\ubb38\uac00\uc758 \ub9d0\uc5d0 \ubc18\ub300\ub85c \ud589\ub3d9\ud558\ub294 \uac83\uc774 \uc633\ub2e4\ub294 \uac83\uc744 \ub4b7\ubc1b\uce68\ud558\ub294 \ub17c\uac70\uc774\uae30\ub3c4 \ud558\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 40\n\n> **\ucc38\ub41c \uc8fc\uc2dd \uac70\ub798 \uc9c0\uc2dd\uc740 \ubaa8\ub4e0 \uc0c1\uc138\ud55c \uac83\uc744 \uc78a\uc5b4\ubc84\ub838\uc744 \ub54c \ub0a8\ub294 \uadf8\uac83\uc774\ub2e4.**\n\n\ubaa8\ub4e0 \uac83\uc744 \uc54c\uc544\uc57c \ud558\ub294 \uac8c \uc544\ub2c8\ub77c, **\uadf8\uac83\uc744 \uc774\ud574\ud558\uace0 \uc0c1\uad00\uad00\uacc4\ub97c \ud30c\uc545\ud558\uba70 \uadf8\uc5d0 \ub9de\uac8c \ud589\ub3d9\ud560 \uc904 \uc54c\uc544\uc57c \ud558\ub294 \uac83\uc774\ub2e4.** \ub108\ubb34 \uac1d\uad00\uc801\uc774\uace0 \uc218\uce58\uc801\uc778 \uac83\uc5d0 \ub9e4\ubab0\ub418\ub2e4 \ubcf4\uba74 \uc0c1\uc0c1\ub825\uc744 \ubc1c\ud718\ud560 \uc218 \uc5c6\ub2e4. \uc22b\uc790\uc640 \uac1d\uad00\uc801\uc778 \uc0ac\uc2e4\uc740 \ubaa8\ub450\uac00 \uc54c\uace0 \uc788\ub2e4. \uadf8 \ud589\uac04 \u2014 \uadf8\uac83\uc740 \uc5b4\ucc0c\ub410\ub4e0 \uc8fc\uad00\uc801\uc77c \uc218\ubc16\uc5d0 \uc5c6\ub294 \uac83\uc774\uace0, \uadf8\uac8c \uc633\ub4e0 \uadf8\ub974\ub4e0 \uc0c1\uad00\uc5c6\uc774 \uadf8\uac83\uc73c\ub85c \ud070\ub3c8\uc744 \ubc8c \uc218 \uc788\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 41\n\n**\uc99d\uad8c\uc0ac\uc5d0\uc11c \ucd94\ucc9c\ud558\ub294 \uc885\ubaa9\uc774\ub098 \ud22c\uc790 \uc870\uc5b8\uc758 90%\ub294 \uc4f8\ubaa8\uc5c6\ub2e4.** \uc8fc\uc2dd\uc744 \uad70\uc911\uc5d0\uac8c \ub5a0\ub118\uae30\uae30 \uc704\ud574 \ubc8c\uc774\ub294 \uc791\uc804 \ub0b4\uc9c0 \ud64d\ubcf4\uc5d0 \ubd88\uacfc\ud558\ub2e4. \uc7a5\ubc0b\ube5b \ubd84\uc11d\uc73c\ub85c \ud3ec\uc7a5\ud558\uace0 \uc8fc\uac00\ub97c \uc870\uc791\ud574 \ube44\uc2f8\uac8c \ub9cc\ub4e0\ub2e4. \uadf8\ub9ac\uace0 \ubaa8\ub4e0 \uc8fc\uc2dd\uc744 \ubd80\ud654\ub1cc\ub3d9\ud30c\uc5d0\uac8c \ub5a0\ub118\uae34\ub2e4. \ubd80\ud654\ub1cc\ub3d9\ud30c\ub294 \ud30c\uc0b0\ud55c\ub2e4. \uadf8\ub7f4\uc2f8\ud55c \uc18c\ubb38 \uc5ed\uc2dc \uc2dc\uc138\ub97c \uc870\uc791\ud558\ub294 \ubc29\ubc95\uc774\ub2e4. **\ud2b9\ubcc4\ud55c \ud22c\uc790 \uc870\uc5b8\uc774 \uc788\ub2e4\uba74 \uadf8\uc640 \ubc18\ub300\ub85c \ud558\ub294 \uac83\uc774 \uc81c\uc77c \uc88b\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 42\n\n**\uc77c\ubc18\uc801\uc778 \ucd94\uc138\ub97c \ubcf4\uace0 \uadf8 \ub2e4\uc74c \uc8fc\uc2dd\uc744 \uc120\ud0dd\ud558\ub77c.** \uc57d\uc138\uc7a5\uc5d0\uc11c \uc88b\uc740 \uc218\uc775\uc744 \ubcf4\ub294 \uac83\uc740 \uc0c1\ub2f9\ud788 \uc5b4\ub835\ub2e4. \uc77c\ubc18\uc801 \ucd94\uc138\ub97c \ubb34\uc2dc\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\uc740 20\ub144 \uc774\uc0c1\uc758 \uacbd\ub825\uc790\uc774\ub2e4. \ud558\uc9c0\ub9cc \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 \ub2ec\uac40\uc774 \ub9d0\ud574\uc8fc\ub294 \uc2dc\uc7a5\uc758 \uc704\uce58\uc640 \uad6d\uba74\uc744 \uc798 \ud574\uc11d\ud55c\ub2e4\uba74, 20\ub144 \uc774\uc0c1\uc758 \uacbd\ub825\uc774 \uc5c6\ub354\ub77c\ub3c4 \uc2dc\uc7a5\uc758 \uc704\uce58\uc640 \uc77c\ubc18\uc801 \ucd94\uc138\ub97c \ud655\uc778\ud560 \uc218 \uc788\uc744 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 43\n\n**\uc5b4\ub5a4 \uc0b0\uc5c5 \ubd84\uc57c\uac00 \uc55e\uc73c\ub85c \uc804\ub9dd\uc774 \uc88b\uc740\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4.** \uc8fc\uc758\ud560 \uc810\uc740, \ub204\uad6c\ub098 \ub2e4 \uc544\ub294 \uc0ac\uc2e4\uc5d0 \uad00\uc2ec\uc744 \uae30\uc6b8\uc774\uc9c0 \ub9d0\uc544\uc57c \ud55c\ub2e4\ub294 \uac83\uc774\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc774\ubbf8 \uc5b4\ub5a4 \ubd84\uc57c\ub97c \uc120\ud0dd\ud574\uc11c \uc8fc\uac00\ub97c \uc0c1\ud55c\uac00\ub85c \uc62c\ub838\ub2e4\uba74, \uadf8\uac83\uc740 \uba87 \ub144 \ud639\uc740 \uc218\uc2ed \ub144\uc744 \uc120\ubc18\uc601\ud55c \uac83\uc77c \uc218 \uc788\ub2e4.\n\n**\ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 \ub2ec\uac40\uc740 \uac1c\ubcc4 \uc0b0\uc5c5\uacfc \uac1c\ubcc4 \uc885\ubaa9\uc5d0\uc11c\ub3c4 \uc720\uc6a9\ud558\ub2e4.** \uac1c\ubcc4 \uc0b0\uc5c5 \ub610\ub294 \uc885\ubaa9\uc774 A1 \uad6d\uba74\uc5d0 \uba38\ubb3c\ub7ec \uc788\uc744 \ub54c \ub300\uc911\ubcf4\ub2e4 \uba3c\uc800 \uc54c\uc544\ub0b4\uc11c \ud22c\uc790\ud574\uc57c \ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 44\n\n**\uc131\uc7a5 \uc0b0\uc5c5\uc758 \ub77c\uc774\ud504\uc0ac\uc774\ud074 (\ubc18\ub3c4\uccb4 \uc608\uc2dc)**\n\n1. \ubc18\ub3c4\uccb4 \ubd84\uc57c\uac00 \uc131\uc7a5\ud558\uba74\uc11c \uc0c8\ub85c\uc6b4 \uae30\uc5c5\ub4e4\uc774 \uc0dd\uaca8\ub09c\ub2e4. \uc774\ub54c \uc131\uc7a5 \uc18d\ub3c4\uc640 \uaddc\ubaa8\uac00 \ucee4\uc11c \ubd80\uc2e4 \uae30\uc5c5\ub3c4 \uc0b4\uc544\ub0a8\ub294\ub2e4.\n2. \uadf8 \ud6c4 \uc0b0\uc5c5 \ubd84\uc57c\uc5d0\uc11c \uc11c\uc11c\ud788 \uc131\uc7a5\ud55c\ub2e4.\n3. \uc131\uc7a5\uc774 \uba48\ucd94\uace0 \uc591\uc9c8\uc5d0 \ub300\ud55c \uc694\uad6c\uac00 \ucee4\uc9c4\ub2e4. \ub300\ubd80\ubd84\uc758 \uae30\uc5c5\uc774 \uc18c\uba78\ud558\uac70\ub098 \ud569\ubcd1\ub41c\ub2e4.\n4. \uc0b0\uc5c5\uc758 \uce68\uccb4\uae30\ub97c \ub9de\uac8c \ub418\uba70 \ubaa8\ub4e0 \uae30\uc5c5\uc774 \uc190\uc2e4\uc744 \ubcf8\ub2e4.\n5. **\uac00\uc7a5 \uac15\ud55c \uba87\uba87 \uae30\uc5c5\ub9cc\uc774 \uc0b4\uc544\ub0a8\uc544 \uc2dc\uc7a5\uc744 \ub098\ub220 \uac16\ub294\ub2e4.** \uc774\ub54c \uc0b4\uc544\ub0a8\uc740 \uae30\uc5c5\uc758 \uc8fc\uac00\ub294 \ub9e4\uc6b0 \uc2f8\ub2e4. \uadf8\ub54c \ud22c\uc790\ud558\ub294 \uac83\uc774 \ud604\uba85\ud558\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 45\n\n**\uc5b4\ub5a4 \uae30\uc5c5\uc774 \ud30c\uc0b0\uc5d0 \uc774\ub974\ub800\ub2e4\ub294 \ub274\uc2a4\ub97c \ubcf4\uba74 \uadf8 \uae30\uc5c5\uc5d0 \uc8fc\ubaa9\ud558\ub77c \u2014 \ud06c\ub77c\uc774\uc2ac\ub7ec \uc0ac\ub840**\n\n\ud06c\ub77c\uc774\uc2ac\ub7ec \uc8fc\uac00\ub294 $50\uc774\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uacbd\uc601\ub09c\uc73c\ub85c \ud30c\uc0b0 \uc9c0\uacbd\uc5d0 \uc774\ub974\ub7ec \uc8fc\uac00\ub294 $3\uc5d0 \ud615\uc131\ud588\ub2e4. \ub098\ub294 $3\uc5d0 \ub9e4\uc785\ud588\ub2e4. \ube0c\ub85c\ucee4\ub294 \ube68\ub9ac \ud314\ub77c\uace0 \ub9d0\ud588\ub2e4. \ud558\uc9c0\ub9cc \ubc18\ub300\ub85c \ud589\ub3d9\ud588\ub2e4. **$50\uc9dc\ub9ac\uac00 $3\uc5d0 \uac70\ub798\ub418\ub294\ub370 \ud314\ub77c\ub2c8 \uc6c3\uae30\ub294 \uc18c\ub9ac\uc600\ub2e4.** \ub9dd\ud558\uba74 $3 \uc190\uc774\uc9c0\ub9cc \ud68c\uc0dd\ud558\uba74 $30\ub294 \ubcfc \uc218 \uc788\uc744 \uac83 \uac19\uc558\ub2e4. \uacb0\uad6d \ud06c\ub77c\uc774\uc2ac\ub7ec \uc8fc\uac00\ub294 $150\uae4c\uc9c0 \uce58\uc19f\uc558\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 46\n\n**\ubd84\uc11d\uac00\ub4e4\uc758 \"\ubcf4\uc720\ud558\ub77c\"\ub294 \ub9d0\uc740 \uc6c3\uae30\ub294 \uc774\uc57c\uae30\uc774\ub2e4.** \uacfc\uac70\uc5d0\ub294 \uc30c\uc9c0\ub9cc \uc9c0\uae08\uc774\ub77c\uba74 \uc0ac\uc9c0 \uc54a\uc744 \uac83\uc774\ub77c\ub294 \ud310\ub2e8\uc774 \ub4e0\ub2e4\uba74 \ud314\uc544\uc57c \ud55c\ub2e4. \ud310\ub2e8\uc758 \uadfc\uac70\ub294 \ub0c9\uc815\ud568\uc744 \uc720\uc9c0\ud55c \uc790\uc2e0\uc758 \uc0dd\uac01\uc5d0 \uc788\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 47\n\n**\ucc28\ud2b8\ub85c \uc218\uc775\uc740 \uac00\ub2a5\ud558\uc9c0\ub9cc \uc190\uc2e4\uc740 \ud544\uc5f0\uc774\ub2e4.** \ucc28\ud2b8\ub85c \uc5b4\uc81c\uc640 \uc624\ub298\uc740 \ubcfc \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uac70\uae30\uae4c\uc9c0\ub2e4. \ucc28\ud2b8\ub85c \ubbf8\ub798\ub97c \ud310\ub2e8\ud558\uc5ec \ud22c\uc790\ud558\ub294 \uac83\uc740 \ub3c8\uc744 \uc783\ub294 \uac83\uc774\ub2e4. \ucc28\ud2b8\ub97c \ub9f9\uc2e0\ud558\ub294 \uc0ac\ub78c\ub4e4 \uac00\uc6b4\ub370 \uc131\uacf5\ud558\ub294 \uc0ac\ub78c\uc740 \uc5c6\uc5c8\ub2e4. **\ucc28\ud2b8\ub97c \uc2e0\uc6a9\ud558\ub294 \uc790\uc758 \uac00\uc7a5 \ud070 \ubd88\ud589\uc740 \ucc98\uc74c \ucc28\ud2b8 \uc774\uc6a9\uc73c\ub85c \ud55c \ubc88 \uc131\uacf5\ud558\uc5ec \uadf8 \ud6c4\ub85c \ucc28\ud2b8\ub97c \ub9f9\uc2e0\ud558\ub294 \uac83\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 48\n\n**\ucf54\uc2a4\ud1a8\ub77c\ub2c8\uac00 \uc778\uc815\ud558\ub294 \ub450 \uac00\uc9c0 \ucc28\ud2b8 \uc774\ub860: W\ud615 \uc774\uc911 \uc0c1\uc2b9 / M\ud615 \uc774\uc911 \ud558\ub77d**\n\n- **W\uc790 \ubaa8\uc591 (\uc774\uc911 \uc0c1\uc2b9):** W\uc790 \ubaa8\uc591\uc758 \ucc28\ud2b8\uc5d0\uc11c \ucd5c\uc800\uc810\uc774 \uc6b0\uc0c1\ud5a5\ud558\uace0 \uc788\ub2e4\uba74 \uacc4\uc18d \uc0c1\uc2b9 \ucd94\uc138.\n- **M\uc790 \ubaa8\uc591 (\uc774\uc911 \ud558\ub77d):** M\uc790 \ubaa8\uc591\uc758 \ucc28\ud2b8\uc5d0\uc11c \ucd5c\uace0\uc810\uc774 \uc6b0\ud558\ud5a5\ud558\uace0 \uc788\ub2e4\uba74 \uacc4\uc18d \ud558\ub77d \ucd94\uc138.\n- W\uc790 \ubaa8\uc591\uc774 \uacc4\uc18d \ubc18\ubcf5\ub418\uba74 \ubc14\ub2e5\uc774\ub77c\ub294 \uc774\uc57c\uae30\ub2e4.\n\n\uc800\uc790\ub294 \ucc28\ud2b8 \uc2e0\ubd09\uc790\uac00 \uc544\ub2c8\uc9c0\ub9cc \uc774 \ub450 \uac00\uc9c0 \ucc28\ud2b8 \uc774\ub860\uc5d0 \ub9ce\uc740 \ub3c4\uc6c0\uc744 \ubc1b\uc558\ub2e4. \uc5b4\ub514\uae4c\uc9c0\ub098 \ubcf4\uc870 \uc218\ub2e8\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 49\n\n**\uba38\ub2c8 \ub9e4\ub2c8\uc800 \u2014 \ub0a8\uc758 \ub3c8\uc73c\ub85c \ud22c\uc790\ud558\uba70 \uc0c1\ub2f9\ud788 \uc5b4\ub9ac\uc11d\uc740 \uc9d1\ub2e8\uc774\ub2e4.** \ud5e4\uc9c0\ud380\ub4dc\uc5d0 \ud22c\uc790\ud558\ub294 \uac83\uc740 \ud55c\uc0ac\ucf54 \ub9d0\ub9ac\uace0 \uc2f6\ub2e4. \ud5e4\uc9c0\ud380\ub4dc, \uc0ac\ubaa8 \ud22c\uc790 \ucee8\uc124\ud134\ud2b8 \u2014 \uadf8\ub4e4\uc758 \uae30\ubd84\uc774 \uace0\uac1d\uc758 \uace0\ud1b5\uc774\ub2e4. \uc218\uc218\ub8cc\ub9cc \ucc59\uae30\uba74 \ub9cc\uc0ac OK\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 50\n\n**\ub098\ub214\uc774 \uc8fc\uc5b4, \uc190\ud574\ub97c \ubcf4\ub294 \uac83\ub3c4 \ubab8\uc758 \uc77c\ubd80\uc774\ub2e4.**\n\n> \ub0b4\uac8c \uc544\ub4e4\uc774 \uc788\ub2e4\uba74, \uccab\uc9f8\ub294 \uc74c\uc545\uac00, \ub458\uc9f8\ub294 \ud654\uac00, \uc14b\uc9f8\ub294 \uc18c\uc124\uac00\ub97c \uc2dc\ud0ac \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \ub137\uc9f8\ub294 \ub2e4\ub978 \uc138 \ud615\uc81c\ub97c \uba39\uc5ec \uc0b4\ub9ac\uae30 \uc704\ud574 \uaf2d \ud22c\uc790\uc790\ub97c \uc2dc\ud0a4\uaca0\ub2e4.\n\n\uc8fc\uc2dd\ud22c\uc790\ub294 \ubbf8\ub798\ub97c \uc704\ud574 \ubc18\ub4dc\uc2dc \ud574\uc57c \ud558\ub294 \uac83\uc774\ub2e4. **\uc808\ub300 \uc783\uc5b4\ubc84\ub9b0 \ub3c8\uc744 \ucc3e\uace0\uc790 \uc560\uc4f0\uc9c0 \ub9d0\ub77c.** \uc190\uc2e4\uc744 \ubcf4\uc558\ub2e4\uba74 \uc989\uc2dc \uadf8\uac83\uc744 \ubc1b\uc544\ub4e4\uc774\uace0 0\ubd80\ud130 \ub2e4\uc2dc \uc2dc\uc791\ud558\ub77c. \uae30\uc655\uc5d0 \ud22c\uc790\ub97c \uc2dc\uc791\ud588\ub2e4\uba74 \uc801\uc5b4\ub3c4 \uc774\uc775\uc744 \ub0b4\ub77c.\n\n\ud380\ub4dc \ub9e4\ub2c8\uc800\uac00 \ud558\ub8e8\uc5d0 16\uc2dc\uac04\uc529 \uc77c\ud55c\ub2e4\ub294 \uac83\uc5d0 \uae30\uc8fd\uc9c0 \ub9c8\ub77c. \uadf8 \uc2dc\uac04\uc758 95%\ub294 \uc2dc\uac04 \ub0ad\ube44\ub2e4. \uc65c\ub0d0\ud558\uba74 \uadf8\ub4e4\uc774 \uc0dd\uac01\ud558\ub294 \ub370 \ud560\uc560\ud558\ub294 \uc2dc\uac04\uc740 \uc5bc\ub9c8 \ub418\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4. **\ub204\uad6c\ub4e0 \uc790\uc2e0\uc758 \ud310\ub2e8\uc5d0 \ub530\ub77c \ub3c5\uc790\uc801\uc73c\ub85c \uc0dd\uac01\ud558\uae30\ub9cc \ud55c\ub2e4\uba74, \uc77c\ud558\ub294 \uc2dc\uac04\uc5d0 \uc0c1\uad00\uc5c6\uc774 \uc774\ubbf8 90%\uc758 \ub3d9\ub8cc\ub97c \uc55e\uc11c \ub098\uac00\ub294 \uac83\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 51\n\n**10\uac00\uc9c0 \ud589\ub3d9 \uc6d0\uce59**\n\n1. \ub9e4\uc785 \uc2dc\uae30\ub77c\uace0 \uc0dd\uac01\ub418\uba74, \uc5b4\ub290 \uc5c5\uc885\uc758 \uc8fc\uc2dd\uc744 \ub9e4\uc785\ud560 \uac83\uc778\uc9c0 \uacb0\uc815\ud558\ub77c.\n2. \uc555\ubc15\uac10\uc5d0 \uc2dc\ub2ec\ub9ac\uc9c0 \uc54a\ub3c4\ub85d \ucda9\ubd84\ud55c \ub3c8\uc744 \uac00\uc9c0\uace0 \ud589\ub3d9\ud558\ub77c.\n3. \ubaa8\ub4e0 \uc77c\uc774 \uc0dd\uac01\uacfc \ub2e4\ub974\uac8c \uc9c4\ud589\ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \uba85\uc2ec\ud558\ub77c. \uadf8\ub9ac\uace0 \ubc18\ub4dc\uc2dc \uc778\ub0b4\ud558\ub77c.\n4. \ud655\uc2e0\uc774 \uc788\uc73c\uba74 \uac15\ud558\uace0 \uace0\uc9d1\uc2a4\ub7fd\uac8c \ubc00\uc5b4\ubd99\uc5ec\ub77c.\n5. \uc720\uc5f0\ud558\uac8c \ud589\ub3d9\ud558\uace0, \uc790\uc2e0\uc758 \uc0dd\uac01\uc774 \uc798\ubabb\ub420 \uc218 \uc788\uc74c\uc744 \uc778\uc815\ud558\ub77c.\n6. \uc644\uc804\ud788 \uc0c8\ub85c\uc6b4 \uc0c1\ud669\uc774 \uc804\uac1c\ub418\uba74 \uc989\uc2dc \ud314\uc544\ub77c.\n7. \ub54c\ub54c\ub85c \uc790\uc2e0\uc774 \ubcf4\uc720\ud55c \uc885\ubaa9\uc758 \ubaa9\ub85d\uc744 \ubcf4\uace0, \uc9c0\uae08\uc774\ub77c\ub3c4 \uc5ed\uc2dc \uc0b4 \uac83\uc778\uc9c0 \uac80\ud1a0\ud558\ub77c.\n8. \ub300\ub2e8\ud55c \uac00\ub2a5\uc131\uc744 \uc608\uacac\ud560 \uc218 \uc788\uc744 \uacbd\uc6b0\uc5d0\ub9cc \uc0ac\ub77c.\n9. \uacc4\uc18d\ud574\uc11c \uc608\uce21\ud560 \uc218 \uc5c6\ub294 \uc704\ud5d8 \uc5ed\uc2dc \ud56d\uc0c1 \uc5fc\ub450\uc5d0 \ub450\ub77c.\n10. \uc790\uc2e0\uc758 \uc8fc\uc7a5\uc774 \uc633\ub2e4 \ud574\ub3c4 \uacb8\uc190\ud558\ub77c.\n\n---\n\n## \ud3ec\uc778\ud2b8 52\n\n**10\uac00\uc9c0 \uae08\uae30\uc0ac\ud56d**\n\n1. \ucd94\ucc9c \uc885\ubaa9\uc744 \ub530\ub974\uc9c0 \ub9d0\uba70, \ube44\ubc00\uc2a4\ub7ec\uc6b4 \uc18c\ubb38\uc5d0 \uadc0 \uae30\uc6b8\uc774\uc9c0 \ub9d0\ub77c.\n2. \ud30c\ub294 \uc0ac\ub78c\uc774 \uc65c \ud30c\ub294\uc9c0, \uc0ac\ub294 \uc0ac\ub78c\uc774 \uc65c \uc0ac\ub294\uc9c0 \uc54c\uace0 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \ub9d0\ub77c. \ub610\ud55c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc790\uc2e0\ubcf4\ub2e4 \ub354 \ub9ce\uc774 \uc54c\uace0 \uc788\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c \uadf8\ub4e4\uc758 \ub9d0\uc5d0 \uadc0 \uae30\uc6b8\uc774\uc9c0 \ub9c8\ub77c.\n3. \uc190\uc2e4\uc744 \ub2e4\uc2dc \ud68c\ubcf5\ud558\ub824\uace0 \ud558\uc9c0 \ub9c8\ub77c.\n4. \uc9c0\ub09c \uc2dc\uc138\uc5d0 \uc5f0\uc5f0\ud558\uc9c0 \ub9c8\ub77c.\n5. \uc8fc\uc2dd\uc744 \uc0ac\ub193\uc740 \ub4a4 \uc5b8\uc820\uac00 \uc8fc\uac00\uac00 \uc624\ub97c \uac83\uc774\ub77c\ub294 \ud76c\ub9dd \uc18d\uc5d0 \uadf8 \uc8fc\uc2dd\uc744 \uc78a\uace0 \uc9c0\ub0b4\uc9c0 \ub9c8\ub77c.\n6. \uc2dc\uc138 \ubcc0\ud654\uc5d0 \ubbfc\uac10\ud558\uac8c \ubc18\uc751\ud558\uc9c0 \ub9c8\ub77c.\n7. \uc5b4\ub514\uc11c \uc218\uc775\uacfc \uc190\uc2e4\uc774 \uc788\uc5c8\ub294\uc9c0 \uacc4\uc18d\ud574\uc11c \uacc4\uc0b0\ud558\uc9c0 \ub9c8\ub77c.\n8. \ub2e8\uae30 \uc218\uc775\uc744 \uc5bb\uae30 \uc704\ud574 \ub2ec\ub9ac\uc9c0 \ub9c8\ub77c.\n9. \uc815\uce58\uc801 \uc131\ud5a5(\uc9c0\uc9c0\ub098 \ubc18\ub300)\uc5d0 \uc758\ud574 \uc2ec\ub9ac\uc801 \uc601\ud5a5\uc744 \ubc1b\uc9c0 \ub9c8\ub77c.\n10. \uc774\uc775\uc744 \ubcf4\uc558\ub2e4\uace0 \ud574\uc11c \uc790\ub9cc\ud574\uc9c0\uc9c0 \ub9c8\ub77c.\n\n---\n\n## \ub9c8\uce58\uba70\n\n80\ub144\uc744 1\ub9cc 2\ucc9c \uc77c\ub85c \uacbd\ud5d8\ud55c \ucf54\uc2a4\ud1a8\ub77c\ub2c8. \uc774\ub7f0 \ucc45\uc740 \uc77d\uace0 \ub098\uba74 \uc9dc\ub9bf\ud558\uace0, \uc774 \uae00\uc744 \ub9c8\uce58\ub294 \uc21c\uac04\uc5d0\ub3c4 \uc804\uc728\uc774 \ud750\ub978\ub2e4. \ubaa8\ub450 \uc774\ud574\ub418\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \ubd84\uba85\ud55c \uac83\uc740 \uc774 \ub0b4\uc6a9\ub4e4\uc774 \uc815\ub9d0 \uc911\uc694\ud558\uba70 \uc774\uac83\ub4e4\uc744 \ub0b4 \uac83\uc73c\ub85c \ub9cc\ub4dc\ub294 \uadf8 \uc21c\uac04 \uc8fc\uc2dd\uc758 \ub2f5\uc744 \ucc3e\uc744 \uc218 \uc788\uc744 \uac83\uc774\ub77c\ub294 \ud655\uc2e0\uc774 \ub4e0\ub2e4.\n\n**\uc774 \ucc45\uc5d0\uc11c \uac00\uc7a5 \uc911\uc694\ud55c \uac1c\ub150\uc744 \uc138 \uac00\uc9c0\ub85c \uc555\ucd95\ud55c\ub2e4\uba74:**\n\n1. **\uc0dd\uac01\ud558\ub77c.** \uc633\ub4e0 \uadf8\ub974\ub4e0, \uc790\uc2e0\ub9cc\uc758 \ud310\ub2e8\uc73c\ub85c \ud589\ub3d9\ud558\ub77c.\n2. **\uacf5\uae09\uacfc \uc218\uc694.** \ubaa8\ub4e0 \uc8fc\uc2dd \uc774\ub860\uc758 \ucd9c\ubc1c\uc810\uc774\ub2e4.\n3. **\uae08\ub9ac\ub97c \uc8fc\uc2dc\ud558\ub77c.** \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ud3ed\ub77d\uc774 \uc624\uace0, \uae08\ub9ac\uac00 \ub0b4\ub9ac\uba74 \uae30\ud68c\uac00 \uc628\ub2e4.\n\n> \ubd80\uc790\uac00 \ub418\ub294 \uc9c0\ub984\uae38\ub85c \ud568\uaed8 \ub2ec\ub824\uac00\uc790.\n"
